#!/usr/bin/env node
/**
 * Loki Mode HTTP API Server (v1.2.0) - LEGACY
 * NOTE: The production API is now the unified FastAPI server at dashboard/server.py (port 57374)
 * This file is kept for backward compatibility only.
 * Zero npm dependencies - uses only Node.js built-ins
 *
 * Usage:
 *   node autonomy/api-server.js [--port 57374]
 *   LOKI_DASHBOARD_PORT=57374 node autonomy/api-server.js
 *   loki api start
 *
 * Endpoints:
 *   GET  /health              - Health check
 *   GET  /status              - Session status
 *   GET  /events              - SSE stream
 *   GET  /logs                - Recent log lines
 *   POST /start               - Start session
 *   POST /stop                - Stop session
 *   POST /pause               - Pause session
 *   POST /resume              - Resume session
 *   GET  /memory              - Cross-project learnings summary
 *   GET  /memory/:type        - Get learnings (patterns|mistakes|successes)
 *   GET  /memory/search?q=    - Search learnings
 *   GET  /memory/stats        - Statistics by project/category
 *   DELETE /memory/:type      - Clear specific learning type
 */

const http = require('http');
const fs = require('fs');
const path = require('path');
const { spawn, execSync } = require('child_process');

// Validate port number is in valid range
function isValidPort(port) {
    return Number.isInteger(port) && port >= 1 && port <= 65535;
}

// Parse command line arguments
function parseArgs() {
    const args = process.argv.slice(2);
    let port = null;

    for (let i = 0; i < args.length; i++) {
        if (args[i] === '--port' || args[i] === '-p') {
            // Ensure next argument exists and is a number
            if (i + 1 < args.length) {
                const val = parseInt(args[i + 1], 10);
                if (isValidPort(val)) {
                    port = val;
                }
                i++; // Skip the value
            }
        } else if (args[i].startsWith('--port=')) {
            const val = parseInt(args[i].split('=')[1], 10);
            if (isValidPort(val)) {
                port = val;
            }
        } else if (/^\d+$/.test(args[i])) {
            // Bare number as port (backwards compatible)
            const val = parseInt(args[i], 10);
            if (isValidPort(val)) {
                port = val;
            }
        }
    }

    return { port };
}

const cliArgs = parseArgs();

// Configuration
const PORT = cliArgs.port || parseInt(process.env.LOKI_DASHBOARD_PORT || '57374');
const MAX_BODY_SIZE = parseInt(process.env.LOKI_API_MAX_BODY || '1048576'); // 1MB default
const LOKI_DIR = process.env.LOKI_DIR || path.join(process.cwd(), '.loki');
const STATE_DIR = path.join(LOKI_DIR, 'state');
const LOG_DIR = path.join(LOKI_DIR, 'logs');

// Find skill directory
function findSkillDir() {
    const candidates = [
        path.join(process.env.HOME || '', '.claude/skills/loki-mode'),
        path.dirname(__dirname),
        process.cwd()
    ];
    for (const dir of candidates) {
        if (fs.existsSync(path.join(dir, 'SKILL.md')) &&
            fs.existsSync(path.join(dir, 'autonomy/run.sh'))) {
            return dir;
        }
    }
    return process.cwd();
}

const SKILL_DIR = findSkillDir();
const RUN_SH = path.join(SKILL_DIR, 'autonomy', 'run.sh');

// Ensure directories exist
fs.mkdirSync(STATE_DIR, { recursive: true });
fs.mkdirSync(LOG_DIR, { recursive: true });

// SSE clients for real-time updates
const sseClients = new Set();

// Utility: read file safely
function readFile(filepath) {
    try {
        return fs.readFileSync(filepath, 'utf8').trim();
    } catch {
        return '';
    }
}

// Utility: check if process is running
function isRunning(pid) {
    if (!pid) return false;
    try {
        process.kill(pid, 0);
        return true;
    } catch {
        return false;
    }
}

// Utility: get version
function getVersion() {
    const versionFile = path.join(SKILL_DIR, 'VERSION');
    return readFile(versionFile) || 'unknown';
}

// Get current status
function getStatus() {
    const pidFile = path.join(LOKI_DIR, 'loki.pid');
    const statusFile = path.join(LOKI_DIR, 'STATUS.txt');
    const pauseFile = path.join(LOKI_DIR, 'PAUSE');
    const stopFile = path.join(LOKI_DIR, 'STOP');

    const pidStr = readFile(pidFile);
    const pid = pidStr ? parseInt(pidStr) : null;
    const running = isRunning(pid);

    let state = 'stopped';
    if (running) {
        if (fs.existsSync(pauseFile)) {
            state = 'paused';
        } else if (fs.existsSync(stopFile)) {
            state = 'stopping';
        } else {
            state = 'running';
        }
    }

    // Read status text
    const statusText = readFile(statusFile);

    // Read orchestrator state if available
    let currentPhase = '';
    let currentTask = '';
    const orchFile = path.join(STATE_DIR, 'orchestrator.json');
    if (fs.existsSync(orchFile)) {
        try {
            const orch = JSON.parse(fs.readFileSync(orchFile, 'utf8'));
            currentPhase = orch.currentPhase || '';
            currentTask = orch.currentTask || '';
        } catch {
            // ignore parse errors
        }
    }

    // Read queue stats
    let pendingTasks = 0;
    const queueFile = path.join(LOKI_DIR, 'queue', 'pending.json');
    if (fs.existsSync(queueFile)) {
        try {
            const queue = JSON.parse(fs.readFileSync(queueFile, 'utf8'));
            pendingTasks = queue.tasks?.length || 0;
        } catch {
            // ignore
        }
    }

    return {
        state,
        pid,
        statusText,
        currentPhase,
        currentTask,
        pendingTasks,
        provider: readFile(path.join(STATE_DIR, 'provider')) || 'claude',
        version: getVersion(),
        lokiDir: LOKI_DIR,
        timestamp: new Date().toISOString()
    };
}

// Broadcast to SSE clients
function broadcast(event, data) {
    const message = `event: ${event}\ndata: ${JSON.stringify(data)}\n\n`;
    for (const client of sseClients) {
        try {
            client.write(message);
        } catch {
            sseClients.delete(client);
        }
    }
}

// Parse JSON body with size limit
function parseBody(req) {
    return new Promise((resolve, reject) => {
        let body = '';
        let size = 0;

        req.on('data', chunk => {
            size += chunk.length;
            if (size > MAX_BODY_SIZE) {
                req.destroy();
                reject(new Error('Request body too large'));
                return;
            }
            body += chunk;
        });

        req.on('end', () => {
            try {
                resolve(body ? JSON.parse(body) : {});
            } catch {
                resolve({});
            }
        });

        req.on('error', () => resolve({}));
    });
}

// Request handler
async function handleRequest(req, res) {
    const url = new URL(req.url, `http://localhost:${PORT}`);
    const method = req.method;
    const pathname = url.pathname;

    // CORS headers
    res.setHeader('Access-Control-Allow-Origin', '*');
    res.setHeader('Access-Control-Allow-Methods', 'GET, POST, DELETE, OPTIONS');
    res.setHeader('Access-Control-Allow-Headers', 'Content-Type, Authorization');

    if (method === 'OPTIONS') {
        res.writeHead(204);
        return res.end();
    }

    // JSON response helper
    const json = (data, status = 200) => {
        res.writeHead(status, { 'Content-Type': 'application/json' });
        res.end(JSON.stringify(data));
    };

    // Routes
    if (method === 'GET' && pathname === '/health') {
        return json({ status: 'ok', version: getVersion() });
    }

    if (method === 'GET' && pathname === '/status') {
        return json(getStatus());
    }

    if (method === 'GET' && pathname === '/events') {
        // Server-Sent Events
        res.writeHead(200, {
            'Content-Type': 'text/event-stream',
            'Cache-Control': 'no-cache',
            'Connection': 'keep-alive'
        });

        // Send initial status
        res.write(`data: ${JSON.stringify(getStatus())}\n\n`);

        sseClients.add(res);

        // Periodic updates every 2 seconds
        const interval = setInterval(() => {
            try {
                res.write(`data: ${JSON.stringify(getStatus())}\n\n`);
            } catch {
                clearInterval(interval);
                sseClients.delete(res);
            }
        }, 2000);

        // Clean up on close, error, or finish
        const cleanup = () => {
            clearInterval(interval);
            sseClients.delete(res);
        };

        req.on('close', cleanup);
        req.on('error', cleanup);
        res.on('error', cleanup);
        res.on('finish', cleanup);
        return;
    }

    if (method === 'GET' && pathname === '/logs') {
        let lines = parseInt(url.searchParams.get('lines'), 10);
        // Validate lines: must be positive, default to 50, cap at 10000
        if (!Number.isInteger(lines) || lines < 1) {
            lines = 50;
        } else if (lines > 10000) {
            lines = 10000;
        }
        const logFile = path.join(LOG_DIR, 'session.log');

        if (!fs.existsSync(logFile)) {
            return json({ logs: [], total: 0 });
        }

        const content = fs.readFileSync(logFile, 'utf8');
        const allLines = content.trim().split('\n').filter(l => l);
        const logs = allLines.slice(-lines);
        return json({ logs, total: allLines.length });
    }

    if (method === 'POST' && pathname === '/start') {
        let body;
        try {
            body = await parseBody(req);
        } catch (err) {
            return json({ error: err.message }, 413);
        }
        const prd = body.prd || '';
        const provider = body.provider || 'claude';
        const parallel = body.parallel || false;
        const background = body.background !== false; // default true for API

        // Check if already running
        const status = getStatus();
        if (status.state === 'running') {
            return json({ error: 'Session already running', pid: status.pid }, 409);
        }

        if (!fs.existsSync(RUN_SH)) {
            return json({ error: 'run.sh not found', path: RUN_SH }, 500);
        }

        // Build arguments
        const args = ['--provider', provider];
        if (parallel) args.push('--parallel');
        if (background) args.push('--bg');
        if (prd) args.push(prd);

        const child = spawn(RUN_SH, args, {
            detached: true,
            stdio: 'ignore',
            cwd: process.cwd()
        });
        child.unref();

        // Save provider for status
        fs.writeFileSync(path.join(STATE_DIR, 'provider'), provider);

        // Broadcast update
        setTimeout(() => broadcast('status', getStatus()), 500);

        return json({
            started: true,
            pid: child.pid,
            provider,
            args
        });
    }

    if (method === 'POST' && pathname === '/stop') {
        const stopFile = path.join(LOKI_DIR, 'STOP');
        const pidFile = path.join(LOKI_DIR, 'loki.pid');

        // Touch STOP file (signals graceful shutdown)
        fs.writeFileSync(stopFile, new Date().toISOString());

        // Also try to kill process directly
        const pidStr = readFile(pidFile);
        if (pidStr) {
            const pid = parseInt(pidStr);
            if (isRunning(pid)) {
                try {
                    process.kill(pid, 'SIGTERM');
                } catch {
                    // ignore
                }
            }
        }

        broadcast('status', getStatus());
        return json({ stopped: true });
    }

    if (method === 'POST' && pathname === '/pause') {
        const pauseFile = path.join(LOKI_DIR, 'PAUSE');
        fs.writeFileSync(pauseFile, new Date().toISOString());
        broadcast('status', getStatus());
        return json({ paused: true });
    }

    if (method === 'POST' && pathname === '/resume') {
        const pauseFile = path.join(LOKI_DIR, 'PAUSE');
        const stopFile = path.join(LOKI_DIR, 'STOP');

        try { fs.unlinkSync(pauseFile); } catch {}
        try { fs.unlinkSync(stopFile); } catch {}

        broadcast('status', getStatus());
        return json({ resumed: true });
    }

    // === Memory/Learnings endpoints ===
    const LEARNINGS_DIR = path.join(process.env.HOME || '', '.loki', 'learnings');

    if (method === 'GET' && pathname === '/memory') {
        // List summary of all learnings
        const result = { patterns: 0, mistakes: 0, successes: 0, location: LEARNINGS_DIR };

        for (const type of ['patterns', 'mistakes', 'successes']) {
            const filepath = path.join(LEARNINGS_DIR, `${type}.jsonl`);
            if (fs.existsSync(filepath)) {
                const content = fs.readFileSync(filepath, 'utf8');
                const count = (content.match(/"description"/g) || []).length;
                result[type] = count;
            }
        }
        return json(result);
    }

    if (method === 'GET' && pathname.startsWith('/memory/search')) {
        const query = url.searchParams.get('q') || '';
        if (!query) {
            return json({ error: 'Missing query parameter ?q=' }, 400);
        }

        const results = [];
        const queryLower = query.toLowerCase();

        for (const type of ['patterns', 'mistakes', 'successes']) {
            const filepath = path.join(LEARNINGS_DIR, `${type}.jsonl`);
            if (!fs.existsSync(filepath)) continue;

            const lines = fs.readFileSync(filepath, 'utf8').split('\n');
            for (const line of lines) {
                if (!line.trim()) continue;
                try {
                    const entry = JSON.parse(line);
                    if (entry.description && entry.description.toLowerCase().includes(queryLower)) {
                        results.push({ type, ...entry });
                    }
                } catch {}
            }
        }
        return json({ query, results, count: results.length });
    }

    if (method === 'GET' && pathname.match(/^\/memory\/(patterns|mistakes|successes)$/)) {
        const type = pathname.split('/')[2];
        const filepath = path.join(LEARNINGS_DIR, `${type}.jsonl`);
        const limit = parseInt(url.searchParams.get('limit')) || 50;
        const offset = parseInt(url.searchParams.get('offset')) || 0;

        if (!fs.existsSync(filepath)) {
            return json({ type, entries: [], total: 0 });
        }

        const entries = [];
        const lines = fs.readFileSync(filepath, 'utf8').split('\n');
        for (const line of lines) {
            if (!line.trim()) continue;
            try {
                const entry = JSON.parse(line);
                if (entry.description) {
                    entries.push(entry);
                }
            } catch {}
        }

        const total = entries.length;
        const paginated = entries.slice(offset, offset + limit);

        return json({ type, entries: paginated, total, limit, offset });
    }

    if (method === 'GET' && pathname === '/memory/stats') {
        const stats = { byCategory: {}, byProject: {} };

        for (const type of ['patterns', 'mistakes', 'successes']) {
            const filepath = path.join(LEARNINGS_DIR, `${type}.jsonl`);
            if (!fs.existsSync(filepath)) continue;

            const lines = fs.readFileSync(filepath, 'utf8').split('\n');
            let count = 0;
            for (const line of lines) {
                if (!line.trim()) continue;
                try {
                    const entry = JSON.parse(line);
                    if (entry.description) {
                        count++;
                        const proj = entry.project || 'unknown';
                        stats.byProject[proj] = (stats.byProject[proj] || 0) + 1;
                    }
                } catch {}
            }
            stats.byCategory[type] = count;
        }
        return json(stats);
    }

    if (method === 'DELETE' && pathname.match(/^\/memory\/(patterns|mistakes|successes)$/)) {
        const type = pathname.split('/')[2];
        const filepath = path.join(LEARNINGS_DIR, `${type}.jsonl`);

        fs.mkdirSync(LEARNINGS_DIR, { recursive: true });
        const header = JSON.stringify({ version: '1.0', created: new Date().toISOString() });
        fs.writeFileSync(filepath, header + '\n');

        return json({ cleared: type });
    }

    // 404 for unknown routes
    json({ error: 'not found', path: pathname }, 404);
}

// Start server
const server = http.createServer(handleRequest);

server.listen(PORT, () => {
    console.log(`Loki Mode API v${getVersion()}`);
    console.log(`Listening on http://localhost:${PORT}`);
    console.log('');
    console.log('Endpoints:');
    console.log('  GET  /health           - Health check');
    console.log('  GET  /status           - Session status');
    console.log('  GET  /events           - SSE stream (real-time updates)');
    console.log('  GET  /logs             - Recent log lines (?lines=50)');
    console.log('  POST /start            - Start session');
    console.log('  POST /stop             - Stop session');
    console.log('  POST /pause            - Pause after current task');
    console.log('  POST /resume           - Resume paused session');
    console.log('  GET  /memory           - Cross-project learnings summary');
    console.log('  GET  /memory/:type     - Get learnings by type');
    console.log('  GET  /memory/search?q= - Search learnings');
    console.log('  GET  /memory/stats     - Statistics');
    console.log('');
    console.log(`LOKI_DIR: ${LOKI_DIR}`);
    console.log(`SKILL_DIR: ${SKILL_DIR}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
    console.log('Shutting down...');
    server.close(() => process.exit(0));
});

process.on('SIGINT', () => {
    console.log('\nShutting down...');
    server.close(() => process.exit(0));
});

#!/usr/bin/env python3
"""Recover token usage for a codex iteration from its session rollout.

W1 in docs/WANG-PRINCIPLES-PLAN.md. Wang states the whole thesis conditionally:
"the right agentic loop AND the right eval or metric for the agents to
optimize". We had the loop and not the metric.

THE PROBLEM, measured on a real FireLater run: every efficiency record showed
input_tokens=0, output_tokens=0, cost_usd=0. Not just cost -- we were recording
NOTHING. `_read_iteration_cost` looks for `.loki/metrics/result-cost-<n>.json`
or `.loki/context/tracking.json`, and on codex neither exists, so cost silently
resolved to 0. A zero is a claim the iteration was free.

That made cost-per-resolved-issue unmeasurable, which is the axis with a
MEASURED 20x industry spread (~$14/pass on Sonnet 4.5; an open harness lands
tasks at ~1/20th Devin's cost). It is the number a buyer compares first.

WHY THE ROLLOUT AND NOT `--json`. codex emits usage on its `turn.completed`
event, but only under `codex exec --json`. The runner pipes codex stdout
through `tee` into the log files it parses for completion signals, so switching
the main dispatch to JSONL would change the format every one of those readers
depends on. codex ALSO persists a session rollout to
~/.codex/sessions/YYYY/MM/DD/rollout-*.jsonl containing `total_token_usage`.
Reading that is a side channel: zero risk to the dispatch pipeline.

FAIL-SAFE: every failure path prints nothing and exits non-zero, so the caller
records "unknown" rather than a fabricated 0 -- the distinction this exists for.

Usage:
    codex-usage.py <since-epoch> [sessions-dir]
Prints one line: input_tokens output_tokens cached_tokens cache_write_tokens
"""

from __future__ import annotations

import os
import sys
from pathlib import Path

try:
    import json
except Exception:  # pragma: no cover
    sys.exit(1)


def _find_usage(obj):
    """Depth-first search for a total_token_usage dict."""
    if isinstance(obj, dict):
        u = obj.get("total_token_usage")
        if isinstance(u, dict):
            return u
        for v in obj.values():
            found = _find_usage(v)
            if found:
                return found
    elif isinstance(obj, list):
        for v in obj:
            found = _find_usage(v)
            if found:
                return found
    return None


def main() -> int:
    if len(sys.argv) < 2:
        return 1
    try:
        since = float(sys.argv[1])
    except ValueError:
        return 1

    root = Path(sys.argv[2]) if len(sys.argv) > 2 else Path.home() / ".codex" / "sessions"
    if not root.is_dir():
        return 1

    # Only rollouts written during THIS iteration. Without the mtime bound a
    # stale session from an earlier run would be attributed to this one, which
    # is worse than reporting nothing: it would look like real data.
    candidates = []
    for p in root.rglob("rollout-*.jsonl"):
        try:
            if p.stat().st_mtime >= since:
                candidates.append(p)
        except OSError:
            continue
    if not candidates:
        return 1

    # The rollout carries CUMULATIVE totals, so the last usage record in the
    # newest matching file is this iteration's total. Summing across files would
    # double-count a resumed session.
    candidates.sort(key=lambda p: p.stat().st_mtime)
    usage = None
    for p in reversed(candidates):
        last = None
        try:
            with p.open(encoding="utf-8", errors="replace") as fh:
                for line in fh:
                    line = line.strip()
                    if not line:
                        continue
                    try:
                        found = _find_usage(json.loads(line))
                    except Exception:
                        continue
                    if found:
                        last = found
        except OSError:
            continue
        if last:
            usage = last
            break

    if not usage:
        return 1

    def _n(key):
        v = usage.get(key, 0)
        return int(v) if isinstance(v, (int, float)) and v >= 0 else 0

    # codex reports input_tokens INCLUSIVE of cached. The pricing tiers charge
    # cached reads at a lower rate, so the uncached remainder is what bills at
    # full input price; emitting the inclusive figure would overstate cost.
    total_in = _n("input_tokens")
    cached = _n("cached_input_tokens")
    uncached = max(total_in - cached, 0)

    out = _n("output_tokens")
    cwrite = _n("cache_write_input_tokens")

    # Cost, if the model is priced. codex reports tokens but never dollars, so
    # without this the whole chain still lands on cost_usd=0 -- tokens recovered
    # and the number that matters still missing.
    #
    # A model we cannot price prints an EMPTY cost field, never 0: "unknown" and
    # "free" are different claims and only one of them is honest.
    cost = ""
    model = os.environ.get("LOKI_CODEX_RESOLVED_MODEL", "").strip()
    if model:
        here = Path(__file__).resolve().parent
        for cand in (here / ".." / ".." / "loki-ts" / "data" / "model-pricing.json",):
            try:
                table = json.loads(cand.read_text(encoding="utf-8")).get("pricing", {})
            except Exception:
                continue
            p = table.get(model)
            if not p:
                # Tier names (small/medium/high) and suffixed variants
                # (gpt-5.6-sol-high) both reach here; match the longest prefix.
                for k in sorted(table, key=len, reverse=True):
                    if model.startswith(k):
                        p = table[k]
                        break
            if p:
                try:
                    cost = "%.6f" % (
                        uncached / 1_000_000 * float(p.get("input", 0))
                        + out / 1_000_000 * float(p.get("output", 0))
                        + cached / 1_000_000 * float(p.get("cache_read", p.get("input", 0)))
                        + cwrite / 1_000_000 * float(p.get("cache_write", p.get("input", 0)))
                    )
                except Exception:
                    cost = ""
            break

    print(uncached, out, cached, cwrite, cost)
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except Exception:
        sys.exit(1)

#!/usr/bin/env node
// generate.mjs -- M2 backend-floor generator (template substitution, NOT heredocs).
//
// Reads the server template files and substitutes tokens derived from a portable
// {resource, fields} descriptor, producing a REAL Express + SQLite backend that
// persists. General by construction: no knowledge of any specific PRD.
//
// Why a Node generator and not a bash heredoc: a heredoc emitting JS collides with
// JS `${...}` template literals and backticks (bit both the M1 yaml and a first
// M2 js heredoc). Templates + substitution keeps generated code reviewable as real
// code. See artifacts/beat-replit-engineering-plan.md (M2 architecture decision).
//
// Usage: node generate.mjs <out_dir> <resource> [field:type ...]
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dir = dirname(fileURLToPath(import.meta.url));
const TPL = join(__dir, "templates", "server");

const [, , outDir, resource, ...fieldArgs] = process.argv;
if (!outDir || !resource) {
  console.error("usage: generate.mjs <out_dir> <resource> [field:type ...]");
  process.exit(2);
}

const fields = (fieldArgs.length ? fieldArgs : ["title:string"]).map((f) => {
  const [name, type = "string"] = f.split(":");
  return { name, type };
});

const cap = resource.charAt(0).toUpperCase() + resource.slice(1);
const coll = resource.endsWith("s") ? resource : resource + "s";

const sqlType = (t) =>
  ["int", "integer", "number", "bool", "boolean"].includes(t) ? "INTEGER" : "TEXT";
const seedVal = (t) =>
  ["int", "integer", "number"].includes(t) ? "1"
  : ["bool", "boolean"].includes(t) ? "0"
  : "'sample value'";

const tokens = {
  __COLL__: coll,
  __RESOURCE_CAP__: cap,
  __COLUMNS_SQL__: fields.map((f) => `  ${f.name} ${sqlType(f.type)},`).join("\n"),
  __SEED_COLS__: fields.length ? fields.map((f) => f.name).join(", ") + "," : "",
  __SEED_VALS__: fields.length ? fields.map((f) => seedVal(f.type)).join(", ") + "," : "",
  __INSERT_COLS__: fields.length ? fields.map((f) => f.name).join(", ") + "," : "",
  __INSERT_PLACEHOLDERS__: fields.length ? fields.map((f) => "@" + f.name).join(", ") + "," : "",
  __BODY_FIELDS__: fields.map((f) => `"${f.name}"`).join(", "),
};

function render(tpl) {
  let out = tpl;
  // Replace longer tokens first so __RESOURCE_CAP__ isn't partially hit, etc.
  for (const key of Object.keys(tokens).sort((a, b) => b.length - a.length)) {
    out = out.split(key).join(tokens[key]);
  }
  return out;
}

