// ListView.tsx -- a data surface that ships all THREE UI states with design
// tokens, wired to the M1 contract hook. This is what "designed, not default"
// looks like: skeleton while loading, an inviting empty state with a CTA, a
// first-run "sample data" banner, and real rows in a tokenized card. It consumes
// the generated hook, so it physically cannot reference a non-contract endpoint.
//
// Generated by contract-scaffold M3 (general: __COLL__/__RESOURCE_CAP__ tokens,
// no product-specific content). Small touches that make users smile: friendly
// copy, an icon, a clear primary action, graceful loading + empty states.
import { useList__RESOURCE_CAP__, useCreate__RESOURCE_CAP__ } from "./generated/api";

export function __RESOURCE_CAP__ListView() {
  const { data, isLoading, isError } = useList__RESOURCE_CAP__();
  const create = useCreate__RESOURCE_CAP__();
  // Orval's react-query hook returns the full response object; the array is at
  // .data.data, typed straight from the OpenAPI contract (a real __RESOURCE_CAP__[]).
  // Reading it wrong is a typecheck error -- the contract-first spine catching a
  // drift in the UI itself.
  const items = data?.data ?? [];
  // A seeded backend (M2) means the first real screen shows sample data, not a void.
  const isFirstRun = items.length > 0 && items.length <= 1;

  // State 1: skeleton -- never a blank flash while loading.
  if (isLoading) {
    return (
      <section className="card" aria-busy="true" aria-label="Loading __COLL__">
        <div className="skeleton" style={{ width: "40%", marginBottom: 12 }} />
        <div className="skeleton" style={{ width: "100%", marginBottom: 8 }} />
        <div className="skeleton" style={{ width: "90%" }} />
      </section>
    );
  }

  if (isError) {
    return (
      <section className="empty" role="alert">
        <p>We couldn't load your __COLL__. Please try again.</p>
      </section>
    );
  }

  // State 2: empty -- a dashed invitation with a clear next action, never a void.
  if (items.length === 0) {
    return (
      <section className="empty">
        <h3 style={{ margin: "0 0 4px" }}>No __COLL__ yet</h3>
        <p style={{ margin: "0 0 16px" }}>Get started by creating your first one.</p>
        <button className="btn-primary" onClick={() => create.mutate({ data: {} as never })}>
          Create __RESOURCE_CAP__
        </button>
      </section>
    );
  }

  // State 3: populated (with a friendly first-run banner when it's sample data).
  return (
    <section>
      {isFirstRun ? (
        <div className="first-run" role="status">
          <span aria-hidden="true">*</span>
          You're viewing sample data. Create a __RESOURCE_CAP__ to make it yours.
        </div>
      ) : null}
      <ul style={{ listStyle: "none", padding: 0, margin: "12px 0 0", display: "grid", gap: 12 }}>
        {items.map((it) => (
          <li key={String((it as { id?: unknown }).id)} className="card">
            <pre style={{ margin: 0, fontFamily: "inherit", whiteSpace: "pre-wrap" }}>
              {JSON.stringify(it, null, 2)}
            </pre>
          </li>
        ))}
      </ul>
    </section>
  );
}

/* theme.css -- design tokens (role-based, NEVER raw hex in components).
 *
 * Why this exists: generated apps look "AI-default" because they scatter raw
 * colors and ship only a happy-path light theme. A real designed app uses ROLE
 * tokens (bg, surface, text, primary, ...) referenced everywhere, ships a
 * parallel dark theme from the same variable block, and honors the OS setting.
 * Swapping one block re-themes the whole app. Modern, high-contrast, accessible.
 *
 * Generated by contract-scaffold M3 (general -- no product-specific colors;
 * a strong neutral+indigo default any greenfield app can ship and re-brand).
 */
:root {
  /* Surfaces */
  --bg: #f7f8fa;
  --surface: #ffffff;
  --surface-2: #f0f2f5;
  --border: #e3e6eb;
  /* Text (AA contrast on --bg / --surface) */
  --text: #1a1d24;
  --text-muted: #5a6472;
  /* Brand accent -- a confident modern indigo (re-brand by editing here only) */
  --primary: #5b35e8;
  --primary-contrast: #ffffff;
  --primary-weak: #ece8fd;
  /* Semantic */
  --ok: #1f9d55;
  --warn: #b7791f;
  --danger: #c2333a;
  /* Shape + depth (subtle, not shadow-heavy) */
  --radius: 12px;
  --radius-sm: 8px;
  --shadow-sm: 0 1px 2px rgba(16, 24, 40, 0.06), 0 1px 3px rgba(16, 24, 40, 0.08);
  --space: 16px;
}

/* Dark theme -- same roles, honored automatically from the OS preference. */
@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f1117;
    --surface: #171a21;
    --surface-2: #1e222b;
    --border: #2a2f3a;
    --text: #eef1f6;
    --text-muted: #9aa4b2;
    --primary: #8b6dff;
    --primary-contrast: #0f1117;
    --primary-weak: #241f3d;
    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.4), 0 1px 3px rgba(0, 0, 0, 0.5);
  }
}
/* Explicit override hook (a theme toggle sets data-theme on <html>). */
:root[data-theme="dark"] {
  --bg: #0f1117; --surface: #171a21; --surface-2: #1e222b; --border: #2a2f3a;
  --text: #eef1f6; --text-muted: #9aa4b2; --primary: #8b6dff;
  --primary-contrast: #0f1117; --primary-weak: #241f3d;
}

* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font: 15px/1.55 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  -webkit-font-smoothing: antialiased;
}
.card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  padding: var(--space);
}
.btn-primary {
  background: var(--primary); color: var(--primary-contrast);
  border: none; border-radius: var(--radius-sm);
  padding: 8px 16px; font-weight: 600; cursor: pointer;
}
.btn-primary:hover { filter: brightness(1.05); }

/* --- the three UI states every data surface ships --- */
/* 1. skeleton (loading) -- a shimmer, never a blank flash */
.skeleton {
  background: linear-gradient(90deg, var(--surface-2) 25%, var(--border) 37%, var(--surface-2) 63%);
  background-size: 400% 100%;
  animation: shimmer 1.4s ease infinite;
  border-radius: var(--radius-sm); height: 16px;
}
@keyframes shimmer { 0% { background-position: 100% 0; } 100% { background-position: 0 0; } }
/* 2. empty state -- a dashed invitation with a CTA, never a void */
.empty {
  border: 1px dashed var(--border); border-radius: var(--radius);
  padding: calc(var(--space) * 2); text-align: center; color: var(--text-muted);
}
/* 3. first-run banner -- "you're viewing sample data" so screen 1 is alive */
.first-run {
  background: var(--primary-weak); border: 1px solid var(--border);
  border-radius: var(--radius); padding: 12px 16px; color: var(--text);
  display: flex; align-items: center; gap: 8px; font-size: 14px;
}

#!/usr/bin/env python3
"""Re-materialize a `claude --json-schema --output-format json` code-review
envelope into the LEGACY 'VERDICT: X\\nFINDINGS:\\n- [severity] description'
text, so the downstream text parsers (_classify_verdict, _severity_is_blocking,
_count_nonblocking_findings in autonomy/run.sh, and the TS mirror) stay
byte-identical. This is the adapter that lets the code-review verdict path adopt
structured output WITHOUT rewriting any consumer.

Contract:
- Reads the raw CLI envelope JSON from env _LOKI_CR_JSON (or stdin if unset).
- Writes legacy text to the path in env _LOKI_CR_OUT (or stdout if unset).
- FAIL-CLOSED: exits non-zero on ANY structural miss so the bash caller falls
  through to the text path. NEVER emits 'VERDICT: PASS' on a miss.
- T1 SAFETY (cross-field enforcement JSON Schema cannot express): if ANY finding
  is Critical or High, the verdict is FORCED to FAIL regardless of the model's
  emitted verdict token. A self-contradictory PASS+Critical can never be waved
  through as non-blocking.

Live-verified envelope shape (claude 2.1.207): top-level 'structured_output'
object is the payload; 'result' is the same JSON as a string (fallback);
'stop_reason' is 'tool_use' for a valid structured turn.

Exit codes (all non-zero == fail-closed, caller falls through to text):
  0 success   2 no input/output target   3 envelope not JSON / not a dict
  4 wrong stop_reason   5 no usable payload   6 missing/invalid verdict
  7 write error
"""
import json
import os
import sys

_BLOCKING = {"CRITICAL", "HIGH"}


def _payload(raw):
    """Return the structured payload from a CLI envelope or bare SDK result."""
    raw = raw.strip()
    if raw.startswith("```") and raw.endswith("```"):
        first_newline = raw.find("\n")
        if first_newline != -1:
            raw = raw[first_newline + 1 : -3].strip()
    try:
        env = json.loads(raw)
    except Exception:
        raise ValueError(3)
    if not isinstance(env, dict):
        raise ValueError(3)

    # A valid structured turn ends with tool_use. A refusal / max_tokens / other
    # stop_reason means the schema was not honored -> fail-closed.
    if env.get("stop_reason") not in (None, "tool_use"):
        raise ValueError(4)

    payload = env.get("structured_output")
    if not isinstance(payload, dict):
        res = env.get("result")
        if isinstance(res, str):
            try:
                payload = json.loads(res)
            except Exception:
                payload = None
    # v8 raw-SDK path: `loki internal sdk-judge` emits the BARE payload object
    # (no CLI envelope), so there is no 'structured_output'/'result' wrapper. If
    # the top-level dict itself carries the payload's 'verdict' key, it IS the
    # payload. The stop_reason guard above already passes for a bare object
    # (no 'stop_reason' key -> None -> allowed).
    if not isinstance(payload, dict) and "verdict" in env:
        payload = env
    if not isinstance(payload, dict):
        raise ValueError(5)

    return payload


def _requirement_contract(payload, manifest_source):
    if isinstance(manifest_source, dict):
        manifest = manifest_source
    else:
        try:
            with open(manifest_source, encoding="utf-8") as handle:
                manifest = json.load(handle)
        except (OSError, json.JSONDecodeError):
            raise ValueError(8)
    if not isinstance(manifest, dict):
        raise ValueError(8)
    expected = manifest.get("requirements")
    actual = payload.get("requirements")
    findings = payload.get("findings")
    if (
        set(payload)
        != {"schema", "spec_sha256", "verdict", "requirements", "findings"}
        or manifest.get("schema") != "loki-requirements-manifest/v1"
        or payload.get("schema") != "loki-requirements-verdict/v1"
        or payload.get("spec_sha256") != manifest.get("spec_sha256")
        or not isinstance(expected, list)
        or not expected
        or not isinstance(actual, list)
        or len(actual) != len(expected)
        or not isinstance(findings, list)
    ):
        raise ValueError(8)

    expected_ids = [item.get("id") for item in expected if isinstance(item, dict)]
    actual_ids = [item.get("id") for item in actual if isinstance(item, dict)]
    if len(expected_ids) != len(expected) or actual_ids != expected_ids:
        raise ValueError(8)
    for item in actual:
        if (
            set(item) != {"id", "status", "evidence"}
            or item.get("status") not in ("PASS", "FAIL")
            or not isinstance(item.get("evidence"), str)
            or not item["evidence"].strip()
            or len(item["evidence"]) > 2000
        ):
            raise ValueError(8)

    for finding in findings:
        if (
            not isinstance(finding, dict)
            or set(finding) != {"severity", "description"}
            or finding.get("severity")
            not in ("Critical", "High", "Medium", "Low")
            or not isinstance(finding.get("description"), str)
            or not finding["description"].strip()
            or len(finding["description"]) > 2000
        ):
            raise ValueError(8)

    verdict = str(payload.get("verdict", "")).strip().upper()
    if verdict not in ("PASS", "FAIL"):
        raise ValueError(6)
    if findings or any(item["status"] != "PASS" for item in actual):
        verdict = "FAIL"
    return verdict, findings


def rematerialize(raw, manifest_source=""):
    """Return legacy VERDICT/FINDINGS text, or raise ValueError(exit_code)."""
    payload = _payload(raw)
    if manifest_source:
        verdict, findings = _requirement_contract(payload, manifest_source)
    else:
        verdict = str(payload.get("verdict", "")).strip().upper()
        findings = payload.get("findings")
    if verdict not in ("PASS", "FAIL"):
        raise ValueError(6)

    if not isinstance(findings, list):
        findings = []

    body = []
    has_blocking = False
    for f in findings:
        if not isinstance(f, dict):
            continue
        sev = str(f.get("severity", "")).strip()
        desc = str(f.get("description", "")).strip()
        if not sev or not desc:
            continue
        if sev.upper() in _BLOCKING:
            has_blocking = True
        # Bracketed severity form matches _severity_is_blocking /
        # _count_nonblocking_findings regexes exactly.
        body.append("- [" + sev + "] " + desc)

    # T1: a Critical/High finding forces FAIL even if the model said PASS.
    if has_blocking:
        verdict = "FAIL"

    lines = ["VERDICT: " + verdict, "FINDINGS:"]
    if body:
        lines.extend(body)
    else:
        lines.append("- None")
    return "\n".join(lines) + "\n"


def main():
    raw = os.environ.get("_LOKI_CR_JSON")
    if raw is None:
        raw = sys.stdin.read()
    out_path = os.environ.get("_LOKI_CR_OUT", "")
    if not raw:
        return 2

    try:
        manifest_source = os.environ.get(
            "_LOKI_CR_REQUIREMENTS_MANIFEST_JSON", ""
        )
        if manifest_source:
            try:
                manifest_source = json.loads(manifest_source)
            except json.JSONDecodeError:
                return 8
        else:
            manifest_source = os.environ.get(
                "_LOKI_CR_REQUIREMENTS_MANIFEST", ""
            )
        text = rematerialize(
            raw, manifest_source
        )
    except ValueError as e:
        return int(e.args[0])

    if out_path:
        try:
            with open(out_path, "w") as fp:
                fp.write(text)
        except OSError:
            return 7
    else:
        sys.stdout.write(text)
    return 0


if __name__ == "__main__":
    sys.exit(main())

