            ctypes.c_int,
            ctypes.c_int,
            ctypes.c_uint64,
            ctypes.c_void_p,
            ctypes.c_int,
        ]
        library.proc_pidinfo.restype = ctypes.c_int
        library.proc_pidfdinfo.argtypes = [
            ctypes.c_int,
            ctypes.c_int,
            ctypes.c_int,
            ctypes.c_void_p,
            ctypes.c_int,
        ]
        library.proc_pidfdinfo.restype = ctypes.c_int
        _DARWIN_LIBPROC = library
    return _DARWIN_LIBPROC


def _darwin_libc():
    global _DARWIN_LIBC
    if _DARWIN_LIBC is None:
        library = ctypes.CDLL(None, use_errno=True)
        library.sysctl.argtypes = [
            ctypes.POINTER(ctypes.c_int),
            ctypes.c_uint,
            ctypes.c_void_p,
            ctypes.POINTER(ctypes.c_size_t),
            ctypes.c_void_p,
            ctypes.c_size_t,
        ]
        library.sysctl.restype = ctypes.c_int
        _DARWIN_LIBC = library
    return _DARWIN_LIBC


def _candidate_pids() -> list[int]:
    if sys.platform == "darwin":
        library = _darwin_libproc()
        count = library.proc_listallpids(None, 0)
        if count <= 0:
            raise RuntimeError("attempt process table query failed")
        capacity = count + 64
        while True:
            values = (ctypes.c_int * capacity)()
            read = library.proc_listallpids(values, ctypes.sizeof(values))
            if read <= 0:
                raise RuntimeError("attempt process table query failed")
            if read < capacity:
                return [pid for pid in values[:read] if pid > 0]
            capacity *= 2
    if sys.platform.startswith("linux"):
        try:
            return [int(name) for name in os.listdir("/proc") if name.isdigit()]
        except OSError as exc:
            raise RuntimeError("attempt process table query failed") from exc
    raise RuntimeError("attempt process table query is unsupported")


class _ProcessRecord(NamedTuple):
    pid: int
    ppid: int
    session_id: int
    identity: str


def _process_record(pid: int) -> _ProcessRecord | None:
    if sys.platform == "darwin":
        info = _DarwinProcBsdInfo()
        size = ctypes.sizeof(info)
        read = _darwin_libproc().proc_pidinfo(pid, 3, 0, ctypes.byref(info), size)
        if read != size or info.pbi_pid != pid or info.pbi_status == 5:
            return None
        try:
            session_id = os.getsid(pid)
        except OSError as exc:
            if exc.errno in (errno.ESRCH, errno.EPERM, errno.EACCES):
                return None
            raise RuntimeError("attempt session identity check failed") from exc
        return _ProcessRecord(
            pid,
            int(info.pbi_ppid),
            session_id,
            f"darwin:{info.pbi_start_tvsec}:{info.pbi_start_tvusec}",
        )
    try:
        with open(
            f"/proc/{pid}/stat", encoding="utf-8", errors="replace"
        ) as handle:
            raw = handle.read()
        fields = raw.rsplit(")", 1)[1].strip().split()
        if fields[0] == "Z":
            return None
        return _ProcessRecord(
            pid,
            int(fields[1]),
            int(fields[3]),
            f"proc:{fields[19]}",
        )
    except (OSError, IndexError, ValueError):
        return None


def _process_identity(pid: int) -> str:
    record = _process_record(pid)
    return record.identity if record is not None else ""


def _process_snapshot() -> dict[int, _ProcessRecord]:
    snapshot: dict[int, _ProcessRecord] = {}
    for pid in _candidate_pids():
        record = _process_record(pid)
        if record is not None:
            snapshot[pid] = record
    return snapshot


class _LineageUnknown(Exception):
    """The lineage marker could not be read because the process is gone.

    Distinct from "the marker is absent". A vanished process is not evidence
    of a lineage violation -- it is the absence of evidence either way.
    """


def _process_has_lineage_token(pid: int, token: str) -> bool:
    needle = f"{_LINEAGE_ENV_NAME}={token}".encode("ascii")
    if sys.platform == "darwin":
        mib = (ctypes.c_int * 3)(1, 49, pid)  # CTL_KERN, KERN_PROCARGS2
        size = ctypes.c_size_t()
        library = _darwin_libc()
        if library.sysctl(mib, 3, None, ctypes.byref(size), None, 0) != 0:
            return False
        if size.value <= 0:
            return False
        buffer = ctypes.create_string_buffer(size.value)
        if library.sysctl(
            mib, 3, buffer, ctypes.byref(size), None, 0
        ) != 0:
            return False
        return needle in bytes(buffer.raw[: size.value]).split(b"\0")
    if sys.platform.startswith("linux"):
        try:
            with open(f"/proc/{pid}/environ", "rb") as handle:
                return needle in handle.read().split(b"\0")
        except FileNotFoundError:
            # The process is already gone. /proc/<pid>/environ disappears the
            # moment a child is reaped, so a short-lived runner that exits
            # before this check runs is indistinguishable here from one that
            # never carried the marker -- and answering "no marker" for it
            # fails the lineage guard and returns 127 as a LAUNCH failure, for
            # a process that in fact launched and completed.
            #
            # Signal "unknown", not "absent". The caller decides, because only
            # the caller knows whether the process it spawned is still alive.
            # macOS never hit this: it has the pipe-handle fallback, so the
            # bug was Linux-only and invisible on a developer Mac.
            raise _LineageUnknown(pid) from None
        except OSError:
            return False
    return False


def _darwin_pipe_handles(pid: int, fd: int) -> frozenset[int]:
    info = _DarwinPipeFdInfo()
    size = ctypes.sizeof(info)
    read = _darwin_libproc().proc_pidfdinfo(
        pid, fd, 6, ctypes.byref(info), size  # PROC_PIDFDPIPEINFO
    )
    if read != size:
        return frozenset()
    return frozenset(
        value
        for value in (
            int(info.pipeinfo.pipe_handle),
            int(info.pipeinfo.pipe_peerhandle),
        )
        if value != 0
    )


def _process_has_lineage_pipe(pid: int, handles: frozenset[int]) -> bool:
    if sys.platform != "darwin" or not handles:
        return False
    library = _darwin_libproc()
    entry_size = ctypes.sizeof(_DarwinProcFdInfo)
    required = library.proc_pidinfo(pid, 1, 0, None, 0)  # PROC_PIDLISTFDS
    if required <= 0:
        return False
    capacity = max(16, (required // entry_size) + 8)
    entries = (_DarwinProcFdInfo * capacity)()
    read = library.proc_pidinfo(
        pid, 1, 0, ctypes.byref(entries), ctypes.sizeof(entries)
    )
    if read <= 0:
        return False
    for entry in entries[: read // entry_size]:
        if entry.proc_fdtype != 6:  # PROX_FDTYPE_PIPE
            continue
        if _darwin_pipe_handles(pid, int(entry.proc_fd)) & handles:
            return True
    return False


def _configure_child_subreaper() -> bool:
    """Make Linux orphans observable without adding a runtime dependency."""
    if not sys.platform.startswith("linux"):
        return False
    libc = ctypes.CDLL(None, use_errno=True)
    prctl = getattr(libc, "prctl", None)
    if prctl is None:
        raise RuntimeError("attempt child subreaper is unavailable")
    prctl.argtypes = [
        ctypes.c_int,
        ctypes.c_ulong,
        ctypes.c_ulong,
        ctypes.c_ulong,
        ctypes.c_ulong,
    ]
    prctl.restype = ctypes.c_int
    if prctl(36, 1, 0, 0, 0) != 0:  # PR_SET_CHILD_SUBREAPER
        raise RuntimeError("attempt child subreaper setup failed")
    return True


class _LineageTracker:
    """Retain birth-token-bound descendants across reparenting and setsid."""

    def __init__(
        self,
        process: subprocess.Popen[bytes],
        subreaper: bool,
        token: str,
        lineage_pipe_handles: frozenset[int],
    ):
        root = _process_record(process.pid)
        if root is None:
            raise RuntimeError("provider attempt identity is unavailable")
        try:
            has_marker = (
                _process_has_lineage_token(root.pid, token)
                or _process_has_lineage_pipe(root.pid, lineage_pipe_handles)
            )
        except _LineageUnknown:
            # The child exited before we could read its marker. That is a
            # completed run, not a lineage violation -- and it is the common
            # case for any runner that finishes fast. Confirm it really is our
            # child (Popen.poll() is authoritative: it reaps only the process
            # this object spawned) before accepting.
            #
            # This stays fail-closed for the case the guard exists to catch: a
            # LIVE process whose marker is genuinely missing still raises,
            # because poll() returns None for it and we fall through.
            has_marker = process.poll() is not None
        if not has_marker:
            raise RuntimeError("provider attempt lineage marker is unavailable")
        self.root_pid = root.pid
        self.session_id = root.session_id
        self.subreaper = subreaper
        self.token = token
        self.lineage_pipe_handles = lineage_pipe_handles
        self._marker_scan_until = 0.0
        self._depths: dict[tuple[int, str], int] = {
            (root.pid, root.identity): 0
        }
        self._proc_events = None
        self._lineage_read_fd = -1
        self._kernel_tracks_children = False
        if sys.platform == "darwin":
            try:
                self._proc_events = select.kqueue()
                self._kernel_tracks_children = self._watch_process(
                    root.pid, track_children=True
                )
                if not self._kernel_tracks_children:
                    self._marker_scan_until = (
                        time.monotonic() + _LINEAGE_DISCOVERY_WINDOW_SECONDS
                    )
            except (AttributeError, OSError) as exc:
                raise RuntimeError("attempt process lineage tracking failed") from exc

    def _watch_process(self, pid: int, track_children: bool = False) -> bool:
        if self._proc_events is None:
            return False
        fflags = select.KQ_NOTE_FORK | select.KQ_NOTE_EXIT
        if track_children:
            fflags |= select.KQ_NOTE_TRACK
        change = select.kevent(
            pid,
            filter=select.KQ_FILTER_PROC,
            flags=select.KQ_EV_ADD | select.KQ_EV_CLEAR,
            fflags=fflags,
        )
        try:
            self._proc_events.control([change], 0, 0)
        except OSError as exc:
            if track_children and exc.errno == errno.ENOTSUP:
                self._watch_process(pid, track_children=False)
                return False
            if exc.errno == errno.ESRCH:
                return False
            raise
        return track_children

    def _depth_for_pid(self, pid: int) -> int:
        depths = [
            depth
            for (tracked_pid, _identity), depth in self._depths.items()
            if tracked_pid == pid
        ]
        return max(depths, default=0)

    def _capture_proc_events(self) -> None:
        if self._proc_events is None:
            return
        while True:
            try:
                events = self._proc_events.control(None, 256, 0)
            except OSError as exc:
                raise RuntimeError("attempt process lineage event read failed") from exc
            for event in events:
                if event.fflags & select.KQ_NOTE_TRACKERR:
                    raise RuntimeError("attempt process lineage event overflow")
                if (
                    not self._kernel_tracks_children
                    and event.fflags
                    & (select.KQ_NOTE_FORK | select.KQ_NOTE_CHILD)
                ):
                    self._marker_scan_until = max(
                        self._marker_scan_until,
                        time.monotonic() + _LINEAGE_DISCOVERY_WINDOW_SECONDS,
                    )
                record = _process_record(int(event.ident))
                if record is None:
                    continue
                parent_pid = (
                    int(event.data)
                    if event.fflags & select.KQ_NOTE_CHILD
                    else record.ppid
                )
                self._depths.setdefault(
                    (record.pid, record.identity),
                    self._depth_for_pid(parent_pid) + 1,
                )
            if len(events) < 256:
                return

    def _snapshot(self) -> dict[int, _ProcessRecord]:
        if not self._kernel_tracks_children:
            return _process_snapshot()
        snapshot: dict[int, _ProcessRecord] = {}
        for pid, identity in tuple(self._depths):
            record = _process_record(pid)
            if record is not None and record.identity == identity:
                snapshot[pid] = record
        return snapshot

    def refresh(self) -> list[tuple[int, str]]:
        self._capture_proc_events()
        snapshot = self._snapshot()
        if time.monotonic() <= self._marker_scan_until:
            for record in snapshot.values():
                ref = (record.pid, record.identity)
                if record.pid == os.getpid() or ref in self._depths:
                    continue
                if _process_has_lineage_token(
                    record.pid, self.token
                ) or _process_has_lineage_pipe(
                    record.pid, self.lineage_pipe_handles
                ):
                    self._depths[ref] = self._depth_for_pid(record.ppid) + 1
                    self._watch_process(record.pid)
        while True:
            active_depths = {
                pid: depth
                for (pid, identity), depth in self._depths.items()
                if pid in snapshot and snapshot[pid].identity == identity
            }
            additions: list[tuple[tuple[int, str], int]] = []
            for record in snapshot.values():
                ref = (record.pid, record.identity)
                if ref in self._depths:
                    continue
                parent_depth = active_depths.get(record.ppid)
                if parent_depth is not None:
                    additions.append((ref, parent_depth + 1))
                elif record.session_id == self.session_id:
                    additions.append((ref, 1))
                elif self.subreaper and record.ppid == os.getpid():
                    # Linux reparents escaped double-fork descendants to this
                    # helper after PR_SET_CHILD_SUBREAPER. This process creates
                    # no other children after the provider leader.
                    additions.append((ref, 1))
            if not additions:
                break
            for ref, depth in additions:
                self._depths.setdefault(ref, depth)
                self._watch_process(ref[0])

        return sorted(
            (
                ref
                for ref in self._depths
                if ref[0] in snapshot and snapshot[ref[0]].identity == ref[1]
            ),
            key=lambda ref: self._depths[ref],
            reverse=True,
        )

    def close(self) -> None:
        if self._proc_events is not None:
            self._proc_events.close()
            self._proc_events = None
        if self._lineage_read_fd >= 0:
            os.close(self._lineage_read_fd)
            self._lineage_read_fd = -1


def spawn_tracked(
    command: list[str], **popen_kwargs: object
) -> tuple[subprocess.Popen[bytes], _LineageTracker]:
    """Spawn a gated session leader and arm identity-bound lineage tracking."""
    if not command or "start_new_session" in popen_kwargs:
        raise ValueError("tracked spawn requires a command and owns its session")

    process: subprocess.Popen[bytes] | None = None
    gate_read = gate_write = -1
    lineage_read = lineage_write = -1
    try:
        subreaper = _configure_child_subreaper()
        token = secrets.token_hex(16)
        child_env = dict(popen_kwargs.pop("env", os.environ))
        child_env[_LINEAGE_ENV_NAME] = token
        child_env.pop(_CONTROL_ENV_NAME, None)
        inherited = tuple(popen_kwargs.pop("pass_fds", ()))
        gate_read, gate_write = os.pipe()
        lineage_read, lineage_write = os.pipe()
        handles = (
            _darwin_pipe_handles(os.getpid(), lineage_read)
            if sys.platform == "darwin"
            else frozenset()
        )
        if sys.platform == "darwin" and not handles:
            raise RuntimeError("attempt lineage pipe identity is unavailable")
        process = subprocess.Popen(
            [sys.executable, "-c", _EXEC_BOOTSTRAP, str(gate_read), *command],
            start_new_session=True,
            env=child_env,
            pass_fds=(*inherited, gate_read, lineage_write),
            **popen_kwargs,
        )
        os.close(gate_read)
        gate_read = -1
        tracker = _LineageTracker(process, subreaper, token, handles)
        tracker._lineage_read_fd = lineage_read
        lineage_read = -1
        os.write(gate_write, b"1")
        os.close(gate_write)
        gate_write = -1
        os.close(lineage_write)
        lineage_write = -1
        return process, tracker
    except BaseException:
        for descriptor in (gate_read, gate_write, lineage_read, lineage_write):
            if descriptor >= 0:
                try:
                    os.close(descriptor)
                except OSError:
                    pass
        if process is not None and process.poll() is None:
            process.terminate()
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait(timeout=1)
        raise


def _signal_process(member: tuple[int, str], sig: int) -> None:
    pid, identity = member
    try:
        if _process_identity(pid) != identity:
            return
        os.kill(pid, sig)
    except ProcessLookupError:
        return
    except OSError as exc:
        if exc.errno != errno.ESRCH:
            raise


def reconcile_lineage(
    process: subprocess.Popen[bytes], tracker: _LineageTracker, grace: float
) -> dict[str, object]:
    """Stop the exact tracked lineage and prove a bounded quiet interval."""
    outcome: dict[str, object] = {
        "checked": True,
        "detected": False,
        "quiescent": False,
        "term_sent": [],
        "kill_sent": [],
        "remaining_pids": [],
        "error": "",
    }
    sent: dict[int, set[tuple[int, str]]] = {
        signal.SIGTERM: set(),
        signal.SIGKILL: set(),
    }

    def refresh() -> list[tuple[int, str]]:
        members = tracker.refresh()
        if any(pid != process.pid for pid, _identity in members):
            outcome["detected"] = True
        return members

    def signal_members(
        members: list[tuple[int, str]], signum: int, field: str
    ) -> None:
        recorded = outcome[field]
        assert isinstance(recorded, list)
        for member in members:
            _signal_process(member, signum)
            if member not in sent[signum]:
                sent[signum].add(member)
                if member[0] != process.pid:
                    recorded.append(member[0])

    started = time.monotonic()
    total_grace = max(
        float(grace) + _QUIESCENCE_SECONDS,
        _QUIESCENCE_SECONDS + _RECONCILE_SCHEDULING_MARGIN_SECONDS,
    )
    final_deadline = started + total_grace
    term_deadline = final_deadline - (
        _QUIESCENCE_SECONDS + _RECONCILE_SCHEDULING_MARGIN_SECONDS
    )
    members = refresh()
    signal_members(members, signal.SIGTERM, "term_sent")
    while members and time.monotonic() < term_deadline:
        time.sleep(_LINEAGE_POLL_SECONDS)
        members = refresh()
        signal_members(members, signal.SIGTERM, "term_sent")

    quiet_since: float | None = None
    while time.monotonic() < final_deadline:
        members = refresh()
        if members:
            quiet_since = None
            signal_members(members, signal.SIGKILL, "kill_sent")
        elif quiet_since is None:
            quiet_since = time.monotonic()
        elif time.monotonic() - quiet_since >= _QUIESCENCE_SECONDS:
            break
        time.sleep(_LINEAGE_POLL_SECONDS)
    members = refresh()
    outcome["remaining_pids"] = [pid for pid, _identity in members]
    outcome["quiescent"] = bool(
        not members
        and quiet_since is not None
        and time.monotonic() - quiet_since >= _QUIESCENCE_SECONDS
    )
    return outcome


def _stop_lineage(
    process: subprocess.Popen[bytes], tracker: _LineageTracker, grace: float
) -> bool:
    outcome = reconcile_lineage(process, tracker, grace)
    members = outcome["remaining_pids"]
    if not outcome["quiescent"]:
        raise RuntimeError(
            "provider attempt lineage is still active: "
            + ",".join(str(pid) for pid in members)
        )

    try:
        process.wait(timeout=1)
    except subprocess.TimeoutExpired:
        raise RuntimeError("provider attempt leader did not stop")
    return bool(outcome["detected"])


def _exit_code(returncode: int) -> int:
    return 128 + abs(returncode) if returncode < 0 else returncode


def _write_output(chunk: bytes, stream: BinaryIO) -> bool:
    try:
        stream.write(chunk)
        stream.flush()
        return True
    except BrokenPipeError:
        return False


def _emit_timeout(reason: str, hard_seconds: int, idle_seconds: int) -> None:
    record = {
        "type": "loki_provider_deadline",
        "reason": reason,
        "hard_seconds": hard_seconds,
        "idle_seconds": idle_seconds,
    }
    print(json.dumps(record, separators=(",", ":")), file=sys.stderr, flush=True)


def _write_control(path: Path) -> bytes:
    record = json.dumps(
        {
            "schema": "loki-deadline-control/v1",
            "pid": os.getpid(),
            "identity": _process_identity(os.getpid()),
        },
        sort_keys=True,
    ).encode("utf-8")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    descriptor = os.open(path, flags, 0o600)
    try:
        os.fchmod(descriptor, 0o600)
        os.write(descriptor, record)
    finally:
        os.close(descriptor)
    return record


def _clear_control(path: Path, expected: bytes) -> None:
    try:
        if path.read_bytes() == expected:
            path.unlink()
    except OSError:
        pass


def cancel_control(path: Path) -> int:
    try:
        info = os.lstat(path)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_nlink != 1
            or stat.S_IMODE(info.st_mode) != 0o600
            or info.st_size > 1024
        ):
            return INTERNAL_EXIT
        record = json.loads(path.read_text(encoding="utf-8"))
        if set(record) != {"schema", "pid", "identity"}:
            return INTERNAL_EXIT
        pid = record["pid"]
        identity = record["identity"]
        if (
            record["schema"] != "loki-deadline-control/v1"
            or not isinstance(pid, int)
            or pid <= 1
            or not isinstance(identity, str)
            or not identity
            or _process_identity(pid) != identity
        ):
            return INTERNAL_EXIT
        os.kill(pid, signal.SIGTERM)
        return 0
    except (OSError, ValueError, json.JSONDecodeError):
        return INTERNAL_EXIT


def _drain_output(process: subprocess.Popen[bytes]) -> None:
    for pipe, stream in (
        (process.stdout, sys.stdout.buffer),
        (process.stderr, sys.stderr.buffer),
    ):
        if pipe is None:
            continue
        while True:
            try:
                chunk = os.read(pipe.fileno(), 65536)
            except BlockingIOError:
                break
            if not chunk:
                break
            if not _write_output(chunk, stream):
                break


def _wait_for_output(
    process: subprocess.Popen[bytes],
    tracker: _LineageTracker,
    hard_seconds: int,
    idle_seconds: int,
) -> tuple[int | None, str | None]:
    if process.stdout is None or process.stderr is None:
        return INTERNAL_EXIT, None

    selector = selectors.DefaultSelector()
    streams = {
        process.stdout.fileno(): sys.stdout.buffer,
        process.stderr.fileno(): sys.stderr.buffer,
    }
    for output_fd, stream in streams.items():
        os.set_blocking(output_fd, False)
        selector.register(output_fd, selectors.EVENT_READ, stream)
    started = last_activity = time.monotonic()
    open_fds = set(streams)

    try:
        while True:
            tracker.refresh()
            now = time.monotonic()
            hard_remaining = hard_seconds - (now - started)
            idle_remaining = (
                idle_seconds - (now - last_activity) if idle_seconds > 0 else hard_remaining
            )
            wait_seconds = max(
                0.0,
                min(hard_remaining, idle_remaining, _LINEAGE_POLL_SECONDS),
            )

            if open_fds:
                for key, _events in selector.select(wait_seconds):
                    try:
                        chunk = os.read(key.fd, 65536)
                    except BlockingIOError:
                        continue
                    if chunk:
                        if not _write_output(chunk, key.data):
                            return 141, None
                        last_activity = time.monotonic()
                    else:
                        selector.unregister(key.fd)
                        open_fds.discard(key.fd)
            elif wait_seconds > 0:
                time.sleep(wait_seconds)

            tracker.refresh()

            returncode = process.poll()
            if returncode is not None:
                for output_fd in tuple(open_fds):
                    while True:
                        try:
                            chunk = os.read(output_fd, 65536)
                        except BlockingIOError:
                            break
                        if not chunk:
                            break
                        if not _write_output(chunk, streams[output_fd]):
                            return 141, None
                return _exit_code(returncode), None

            now = time.monotonic()
            if now - started >= hard_seconds:
                return None, "hard_timeout"
            if idle_seconds > 0 and now - last_activity >= idle_seconds:
                return None, "idle_timeout"
    finally:
        selector.close()


def main() -> int:
    if len(sys.argv) == 3 and sys.argv[1] == "cancel":
        return cancel_control(Path(sys.argv[2]))
    if len(sys.argv) < 5:
        return INTERNAL_EXIT
    try:
        hard_seconds = int(sys.argv[1])
        kill_grace = int(sys.argv[2])
        if sys.argv[3] == "--":
            idle_seconds = 0
            command = sys.argv[4:]
        elif len(sys.argv) >= 6 and sys.argv[4] == "--":
            idle_seconds = int(sys.argv[3])
            command = sys.argv[5:]
        else:
            return INTERNAL_EXIT
    except ValueError:
        return INTERNAL_EXIT
    if hard_seconds <= 0 or kill_grace <= 0 or idle_seconds < 0 or not command:
        return INTERNAL_EXIT
    if idle_seconds >= hard_seconds and idle_seconds != 0:
        return INTERNAL_EXIT

    process: subprocess.Popen[bytes] | None = None
    tracker: _LineageTracker | None = None
    try:
        process, tracker = spawn_tracked(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            bufsize=0,
        )
    except (OSError, RuntimeError):
        return INTERNAL_EXIT

    def forward_and_exit(signum: int, _frame: object) -> None:
        try:
            _stop_lineage(process, tracker, min(float(kill_grace), 0.5))
        except (PermissionError, RuntimeError):
            raise SystemExit(INTERNAL_EXIT)
        raise SystemExit(128 + signum)

    for forwarded in (signal.SIGTERM, signal.SIGINT, signal.SIGHUP):
        signal.signal(forwarded, forward_and_exit)

    control_path: Path | None = None
    control_record = b""
    try:
        try:
            raw_control_path = os.environ.get(_CONTROL_ENV_NAME, "")
            if raw_control_path:
                control_path = Path(raw_control_path)
                control_record = _write_control(control_path)
            returncode, timeout_reason = _wait_for_output(
                process, tracker, hard_seconds, idle_seconds
            )
        except (OSError, PermissionError, RuntimeError):
            try:
                _stop_lineage(process, tracker, float(kill_grace))
            except (PermissionError, RuntimeError):
                pass
            return INTERNAL_EXIT
        if timeout_reason is not None:
            _emit_timeout(timeout_reason, hard_seconds, idle_seconds)
            try:
                _stop_lineage(process, tracker, float(kill_grace))
            except (PermissionError, RuntimeError):
                return INTERNAL_EXIT
            _drain_output(process)
            return TIMEOUT_EXIT

        if returncode == 141:
            try:
                _stop_lineage(process, tracker, float(kill_grace))
            except (PermissionError, RuntimeError):
                return INTERNAL_EXIT
            return 141

        # A provider must not leave tool processes alive after its own exit.
        try:
            had_descendants = _stop_lineage(process, tracker, 0.1)
        except (PermissionError, RuntimeError):
            return INTERNAL_EXIT
        if had_descendants:
            return INTERNAL_EXIT
        return returncode if returncode is not None else INTERNAL_EXIT
    finally:
        if control_path is not None and control_record:
            _clear_control(control_path, control_record)
        tracker.close()


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Failure memory: the agent gets better at YOUR repo by having been wrong in it.

WHY THIS EXISTS. Neither competitor learns from being wrong, and one of them
shipped a UI to manage that fact.

Factory AI has no memory system at all -- verified by grep over their whole doc
corpus. AGENTS.md is hand-authored by the human, AutoWiki regenerates from CODE
rather than from outcomes, QA failure learning is `suggest_in_report` (a human
reads it and decides), and mission-generated skills live under {missionDir} and
are DISCARDED with the mission. Devin has a real memory layer, but every session
starts from a fresh snapshot copy and all changes are discarded at teardown --
and their Session Insights ships a "Misleading Knowledge" tab enumerating memory
items that led Devin astray. They built an interface for their memory poisoning
output.

So on both systems, an agent that failed a gate in your repo yesterday starts
today knowing nothing about it.

WHAT MAKES THIS DIFFERENT, AND WHY IT IS NOT THE SAME TRAP. The reason Devin
needed a "Misleading Knowledge" tab is that memory written from an agent's own
narration is unfalsifiable: it records what the agent BELIEVED, which is exactly
what was wrong when it failed. So nothing here is written from narration. A
lesson is created only from a MEASURED event -- a named gate that failed, with
its verdict -- and it carries the evidence that produced it. A lesson whose
evidence no longer holds can be retired mechanically instead of accumulating.

This is deliberately built on the outcome ledger's discipline: a lesson is
recorded only when the event that justifies it is a fact, and everything else
reports UNKNOWN with a named reason rather than being written as a weak guess.

WHAT IT DOES NOT DO. It does not summarize, generalize, or ask a model what the
lesson "means". A generalization is a judgement, and a judgement stored as memory
is indistinguishable from a fact by the next reader -- which is the poisoning
mechanism. It stores the gate, the verdict, the evidence, and a count. Deciding
what that implies stays with whoever reads it.
"""

from __future__ import annotations

import json
import os
import sys
from datetime import datetime, timezone

SCHEMA_VERSION = "1.0"

UNKNOWN = "UNKNOWN"

REASONS = {
    "no_gate": "no gate name was given, so there is nothing to attribute the failure to",
    "no_evidence": "no evidence was given, so the lesson would be unfalsifiable",
    "no_lessons": "no failure lessons recorded for this project",
    "unreadable": "the lesson store exists but could not be parsed",
}


def _path(loki_dir):
    return os.path.join(loki_dir, "memory", "failures.jsonl")


def record_failure(loki_dir, gate, verdict, evidence, run_id=None):
    """Turn a measured gate failure into a durable, falsifiable lesson.

    Requires EVIDENCE. A lesson without it is the agent's own account of why it
    failed, which is precisely the unfalsifiable memory that made Devin's need a
    "Misleading Knowledge" tab. If we cannot say what was observed, we do not
    write anything.
    """
    if not gate:
        return {"status": UNKNOWN, "reason": "no_gate", "detail": REASONS["no_gate"]}
    if not evidence:
        return {"status": UNKNOWN, "reason": "no_evidence",
                "detail": REASONS["no_evidence"]}

    rec = {
        "schema_version": SCHEMA_VERSION,
        "recorded_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "gate": gate,
        "verdict": verdict or "FAIL",
        # The falsifiability anchor. A future reader can check whether this still
        # holds instead of taking the lesson on faith.
        "evidence": evidence,
        "run_id": run_id or "",
        # Deliberately absent: any summary, generalization, or "what this means".
        # A judgement stored beside facts becomes indistinguishable from one.
    }

    p = _path(loki_dir)
    try:
        os.makedirs(os.path.dirname(p), exist_ok=True)
        with open(p, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(rec, sort_keys=True) + "\n")
    except OSError as exc:
        return {"status": UNKNOWN, "reason": "unreadable", "detail": str(exc)}
    return {"status": "recorded", "path": p, "record": rec}


def recall(loki_dir, gate=None):
    """What has actually gone wrong here before.

    Returns counts per gate, most-failed first. Counts, not prose: "the mock
    integrity gate has failed here 6 times" is a fact a reader can act on, while
    "this repo tends to have mocking problems" is a generalization that sounds
    the same and is not checkable.
    """
    p = _path(loki_dir)
    if not os.path.isfile(p):
        return {"status": UNKNOWN, "reason": "no_lessons",
                "detail": REASONS["no_lessons"]}

    per_gate, recent, bad = {}, [], 0
    try:
        with open(p, "r", encoding="utf-8") as fh:
            for line in fh:
                line = line.strip()
                if not line:
                    continue
                try:
                    r = json.loads(line)
                except ValueError:
                    # Counted, never silently skipped: a memory that quietly
                    # drops what it cannot read is worse than one that admits it.
                    bad += 1
                    continue
                g = r.get("gate")
                if not g or (gate and g != gate):
                    continue
                per_gate[g] = per_gate.get(g, 0) + 1
                recent.append(r)
    except OSError as exc:
        return {"status": UNKNOWN, "reason": "unreadable", "detail": str(exc)}

    if not per_gate:
        return {"status": UNKNOWN, "reason": "no_lessons",
                "detail": REASONS["no_lessons"]}

    return {
        "status": "measured",
        "unparseable_lines": bad,
        "by_gate": dict(sorted(per_gate.items(), key=lambda kv: -kv[1])),
        "total": sum(per_gate.values()),
        # Newest last so a reader sees the current state at the bottom, matching
        # how the file itself is ordered.
        "recent": recent[-5:],
    }


def prompt_context(loki_dir, limit=3):
    """The lines worth putting in front of the next run.

    Returns bare facts. A repo where the same gate has failed repeatedly is
    information the next iteration should have; what to DO about it is left to
    the agent, because prescribing the fix from a count would be inventing a
    causal claim the data does not contain.
    """
    r = recall(loki_dir)
    if r.get("status") != "measured":
        return {"status": r.get("status"), "reason": r.get("reason"), "lines": []}
    lines = []
    for gate, n in list(r["by_gate"].items())[:limit]:
        if n > 1:
            lines.append(f"the {gate} gate has failed {n} times in this repo before")
        else:
            lines.append(f"the {gate} gate has failed here before")
    return {"status": "measured", "lines": lines}


def main(argv):
    if not argv:
        print("usage: failure_memory.py record|recall|context [...]", file=sys.stderr)
        return 2
    action = argv[0]
    cwd = os.environ.get("LOKI_FAILMEM_CWD") or os.getcwd()
    loki_dir = os.environ.get("LOKI_DIR") or os.path.join(cwd, ".loki")

    kv = {}
    for a in argv[1:]:
        if a.startswith("--") and "=" in a:
            k, v = a[2:].split("=", 1)
            kv[k] = v

    if action == "record":
        res = record_failure(loki_dir, kv.get("gate"), kv.get("verdict"),
                             kv.get("evidence"), kv.get("run_id"))
    elif action == "recall":
        res = recall(loki_dir, kv.get("gate"))
    elif action == "context":
        res = prompt_context(loki_dir)
    else:
        print(f"unknown action: {action}", file=sys.stderr)
        return 2

    print(json.dumps(res, indent=2))
    return 0 if res.get("status") in ("recorded", "measured") else 3


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

#!/usr/bin/env python3
"""Detect rendered mock operational data with collection-level binding."""

from __future__ import annotations

import hashlib
import json
import os
import re
import sys
from dataclasses import dataclass
from pathlib import Path
from typing import Iterable


RESOLUTION_EXTENSIONS = (
    ".ts", ".tsx", ".mts", ".js", ".jsx", ".mjs", ".cts", ".cjs", ".vue", ".svelte",
)
SOURCE_EXTENSIONS = frozenset(RESOLUTION_EXTENSIONS)
SOURCE_INDEX_EXCLUDE = re.compile(
    r"(^|/)(node_modules|\.git|\.loki|\.next|\.cache|dist|build|out|coverage|"
    r"storybook)(/|$)|\.d\.(?:ts|mts|cts)$",
    re.IGNORECASE,
)
RENDER_EXCLUDE = re.compile(
    r"(^|/)(node_modules|\.git|\.loki|\.next|\.cache|dist|build|out|coverage|"
    r"__mocks__|__tests__|__fixtures__|fixtures?|mocks?|stories|storybook)(/|$)"
    r"|\.(test|spec|stories|story|mock|fixture)\."
    r"|\.d\.(?:ts|mts|cts)$|(^|/)msw|(^|/)setup",
    re.IGNORECASE,
)
DECLARATION = re.compile(
    r"\b(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*"
    r"(?::[^=;]+)?=\s*",
    re.MULTILINE,
)
NAMED_IMPORT = re.compile(
    r"\bimport\s*\{([^}]+)\}\s*from\s*[\"']([^\"']+)[\"']",
    re.MULTILINE,
)
DEFAULT_IMPORT = re.compile(
    r"\bimport\s+(?!type\b)([A-Za-z_$][\w$]*)\s+from\s*[\"']([^\"']+)[\"']",
    re.MULTILINE,
)
DEFAULT_EXPORT_IDENTIFIER = re.compile(
    r"\bexport\s+default\s+([A-Za-z_$][\w$]*)\s*;?",
    re.MULTILINE,
)
DEFAULT_EXPORT = re.compile(r"\bexport\s+default\s+", re.MULTILINE)
NAMED_REEXPORT = re.compile(
    r"\bexport\s*\{([^}]+)\}\s*from\s*[\"']([^\"']+)[\"']",
    re.MULTILINE,
)
STAR_REEXPORT = re.compile(
    r"\bexport\s*\*\s*from\s*[\"']([^\"']+)[\"']",
    re.MULTILINE,
)
FAKER = re.compile(r"\bfaker\s*\.", re.IGNORECASE)
PLACEHOLDER_VALUE = re.compile(
    r"lorem ipsum|john doe|jane doe|dummy data|example@example"
    r"|\b(?:mock|fake|dummy|placeholder)(?:Data|Users?|Orders?|Customers?|Rows?|Records?)\b",
    re.IGNORECASE,
)
EXPLICIT_MOCK_TOKEN = {"mock", "fake", "dummy", "placeholder", "sample", "fixture"}
OPERATIONAL_TOKEN = {
    "user", "users", "order", "orders", "customer", "customers", "account",
    "accounts", "invoice", "invoices", "payment", "payments", "transaction",
    "transactions", "record", "records", "row", "rows", "ticket", "tickets",
    "message", "messages", "notification", "notifications", "activity",
    "activities", "event", "events", "metric", "metrics", "analytics",
    "dashboard", "task", "tasks", "note", "notes", "product", "products",
    "member", "members", "project", "projects", "job", "jobs", "lead",
    "leads", "contact", "contacts", "subscription", "subscriptions",
    "deployment", "deployments", "build", "builds",
}
STATIC_CONTENT_TOKEN = {
    "feature", "features", "benefit", "benefits", "plan", "plans", "pricing",
    "testimonial", "testimonials", "story", "stories", "comparison",
    "comparisons", "faq", "faqs", "navigation", "nav", "logo", "logos",
    "step", "steps", "tier", "tiers", "quote", "quotes",
}
JSX_TAG = re.compile(r"<[A-Za-z][A-Za-z0-9_.:-]*\b")
DIRECT_COLLECTION_PROP = re.compile(
    r"<(?:DataGrid|Table|List|Grid)\b[^>]*\b(?:rows|dataSource|items|data)\s*=\s*"
    r"\{\s*([A-Za-z_$][\w$]*)[^{}]{0,500}\}",
    re.IGNORECASE | re.DOTALL,
)
VUE_LOOP = re.compile(
    r"\bv-for\s*=\s*[\"'][^\"']*\bin\s+([A-Za-z_$][\w$]*)[^\"']*[\"']",
    re.IGNORECASE,
)
SVELTE_LOOP = re.compile(
    r"\{#each\s+([A-Za-z_$][\w$]*)\s+as\b",
    re.IGNORECASE,
)
DIRECT_INLINE_MAP = re.compile(
    r"\[\s*\{(?P<body>.{0,4000}?)\}\s*(?:,\s*\{.{0,4000}?\}\s*)*\]"
    r"\s*\.map\s*\(",
    re.DOTALL,
)
OPERATIONAL_FIELD = re.compile(
    r"\b(?:id|email|role|status|amount|total|customer|order|user|invoice|payment|transaction)\s*:",
    re.IGNORECASE,
)
STRONG_OPERATIONAL_FIELD = re.compile(
    r"\b(?:email|role|amount|total|customer|order|user|invoice|payment|transaction)\s*:",
    re.IGNORECASE,
)
STATIC_CONTENT_FIELD = re.compile(
    r"\b(?:feature|title|description|benefit|plan|price|quote|question|answer|logo|step|tier)\s*:",
    re.IGNORECASE,
)
STATE_DECLARATION = re.compile(
    r"\b(?:export\s+)?(?:const|let|var)\s*\[\s*([A-Za-z_$][\w$]*)[^\]]*\]"
    r"\s*(?::[^=;]+)?=\s*",
    re.MULTILINE,
)


@dataclass(frozen=True)
class Declaration:
    file: str
    name: str
    expression: str
    line: int


def _identifier_tokens(name: str) -> list[str]:
    expanded = re.sub(r"([a-z0-9])([A-Z])", r"\1 \2", name)
    return [token.lower() for token in re.split(r"[^A-Za-z0-9]+", expanded) if token]


def _read_initializer(source: str, start: int) -> str:
    """Read a JavaScript initializer through its top-level semicolon."""

    depth = 0
    quote = ""
    escaped = False
    index = start
    limit = min(len(source), start + 50000)
    while index < limit:
        char = source[index]
        next_char = source[index + 1] if index + 1 < limit else ""
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            index += 1
            continue
        if char in "\"'`":
            quote = char
        elif char == "/" and next_char == "/":
            newline = source.find("\n", index + 2, limit)
            index = limit if newline < 0 else newline
            continue
        elif char == "/" and next_char == "*":
            close = source.find("*/", index + 2, limit)
            index = limit if close < 0 else close + 2
            continue
        elif char in "([{":
            depth += 1
        elif char in ")]}" and depth > 0:
            depth -= 1
        elif char == ";" and depth == 0:
            return source[start:index]
        elif char == "\n" and depth == 0:
            remainder = source[index + 1:limit]
            if re.match(
                r"\s*(?:(?:export\s+)?(?:const|let|var|function|class)\b|"
                r"import\b|export\s+(?:default|\{|\*))",
                remainder,
            ):
                return source[start:index]
        index += 1
    return source[start:limit]


def _declarations(relative: str, source: str) -> dict[str, Declaration]:
    found: dict[str, Declaration] = {}
    for match in DECLARATION.finditer(source):
        name = match.group(1)
        found[name] = Declaration(
            file=relative,
            name=name,
            expression=_read_initializer(source, match.end()),
            line=source.count("\n", 0, match.start()) + 1,
        )
    for match in STATE_DECLARATION.finditer(source):
        name = match.group(1)
        found[name] = Declaration(
            file=relative,
            name=name,
            expression=_read_initializer(source, match.end()),
            line=source.count("\n", 0, match.start()) + 1,
        )
    return found


def _mock_reason(declaration: Declaration) -> str:
    tokens = _identifier_tokens(declaration.name)
    expression = declaration.expression
    static_content = any(token in STATIC_CONTENT_TOKEN for token in tokens)
    if any(token in EXPLICIT_MOCK_TOKEN for token in tokens) and not static_content:
        return "explicit_mock_collection"
    if FAKER.search(expression):
        return "faker_collection"
    if PLACEHOLDER_VALUE.search(expression):
        return "placeholder_collection"
    inline_objects = re.match(
        r"\s*(?:(?:useState|ref|reactive|readonly|\$state)"
        r"(?:<[^>]{1,500}>)?\s*\(\s*)?\[\s*\{",
        expression,
    ) is not None
    operational_fields = len(OPERATIONAL_FIELD.findall(expression)) >= 2
    strong_operational = STRONG_OPERATIONAL_FIELD.search(expression) is not None
    if inline_objects and not static_content and (
        any(token in OPERATIONAL_TOKEN for token in tokens)
        or (operational_fields and strong_operational)
    ):
        return "inline_operational_collection"
    if (
        re.match(r"\s*Array\.from\s*\(", expression)
        and any(token in OPERATIONAL_TOKEN for token in tokens)
        and not static_content
        and re.search(r"=>\s*\(?\s*\{", expression)
    ):
        return "generated_operational_collection"
    return ""


def _mask_non_code(source: str) -> str:
    """Mask comments and strings while preserving positions and newlines."""

    masked = list(source)
    index = 0
    while index < len(source):
        char = source[index]
        next_char = source[index + 1] if index + 1 < len(source) else ""
        if char == "/" and next_char == "/":
            end = source.find("\n", index + 2)
            end = len(source) if end < 0 else end
            for position in range(index, end):
                masked[position] = " "
            index = end
            continue
        if char == "/" and next_char == "*":
            end = source.find("*/", index + 2)
            end = len(source) if end < 0 else end + 2
            for position in range(index, end):
                if masked[position] != "\n":
                    masked[position] = " "
            index = end
            continue
        if char in "\"'`":
            quote = char
            end = index + 1
            escaped = False
            while end < len(source):
                current = source[end]
                if escaped:
                    escaped = False
                elif current == "\\":
                    escaped = True
                elif current == quote:
                    end += 1
                    break
                end += 1
            for position in range(index, end):
                if masked[position] != "\n":
                    masked[position] = " "
            index = end
            continue
        index += 1
    return "".join(masked)


def _balanced_parenthesized(source: str, opening: int) -> str:
    if opening < 0 or opening >= len(source) or source[opening] != "(":
        return ""
    depth = 0
    for index in range(opening, min(len(source), opening + 50000)):
        if source[index] == "(":
            depth += 1
        elif source[index] == ")":
            depth -= 1
            if depth == 0:
                return source[opening:index + 1]
    return ""


def _named_callback_renders_jsx(source: str, call: str) -> bool:
    callback = re.match(r"\(\s*([A-Za-z_$][\w$]*)\s*(?:,|\))", call)
    if not callback:
        return False
    callback_name = callback.group(1)
    for declaration in _declarations("", source).values():
        if (
            declaration.name == callback_name
            and "=>" in declaration.expression
            and JSX_TAG.search(declaration.expression)
        ):
            return True
    name = re.escape(callback_name)
    function = re.search(
        rf"\bfunction\s+{name}\s*\([^)]*\)\s*\{{.{{0,5000}}?\breturn\s+(<[A-Za-z][A-Za-z0-9_.:-]*\b)",
        source,
        re.DOTALL,
    )
    return function is not None


def _skip_balanced_backward(source: str, index: int) -> int:
    """Return the index before a balanced parenthesized expression."""

    depth = 0
    quote = ""
    escaped = False
    while index >= 0:
        char = source[index]
        if quote:
            if escaped:
                escaped = False
            elif char == "\\":
                escaped = True
            elif char == quote:
                quote = ""
            index -= 1
            continue
        if char in "\"'`":
            quote = char
        elif char == ")":
            depth += 1
        elif char == "(":
            depth -= 1
            if depth == 0:
                return index - 1
        index -= 1
    return -1


def _map_collection_root(source: str, map_dot: int) -> str:
    """Trace `collection.filter(...).map` back to its root identifier."""

    index = map_dot - 1
    candidate = ""
    while index >= 0:
        while index >= 0 and source[index].isspace():
            index -= 1
        if index >= 0 and source[index] == ")":
            index = _skip_balanced_backward(source, index)
            while index >= 0 and source[index].isspace():
                index -= 1
        end = index + 1
        while index >= 0 and (source[index].isalnum() or source[index] in "_$"):
            index -= 1
        if end == index + 1:
            return candidate
        candidate = source[index + 1:end]
        while index >= 0 and source[index].isspace():
            index -= 1
        if index >= 0 and source[index] == "?":
            index -= 1
        if index >= 0 and source[index] == ".":
            index -= 1
            continue
        return candidate
    return candidate


def _rendered_symbols(source: str) -> set[str]:
    rendered: set[str] = set()
    structural = _mask_non_code(source)
    for match in re.finditer(r"(?:\?\.|\.)\s*map\s*\(", structural):
        call = _balanced_parenthesized(structural, match.end() - 1)
        if JSX_TAG.search(call) or _named_callback_renders_jsx(structural, call):
            root = _map_collection_root(structural, match.start())
            if root:
                rendered.add(root)
    rendered.update(match.group(1) for match in DIRECT_COLLECTION_PROP.finditer(structural))
    rendered.update(match.group(1) for match in VUE_LOOP.finditer(source))
    rendered.update(match.group(1) for match in SVELTE_LOOP.finditer(source))
    return rendered


def _named_imports(source: str) -> dict[str, tuple[str, str]]:
    imports: dict[str, tuple[str, str]] = {}
    for match in NAMED_IMPORT.finditer(source):
        module = match.group(2)
        for raw_binding in match.group(1).split(","):
            binding = raw_binding.strip()
            if not binding:
                continue
            parts = re.split(r"\s+as\s+", binding, maxsplit=1)
            imported = parts[0].strip()
            local = parts[-1].strip()
            if re.fullmatch(r"[A-Za-z_$][\w$]*", imported) and re.fullmatch(
                r"[A-Za-z_$][\w$]*", local
            ):
                imports[local] = (module, imported)
    for match in DEFAULT_IMPORT.finditer(source):
        imports[match.group(1)] = (match.group(2), "default")
    return imports


def _jsonc_object(path: Path) -> dict[str, object]:
    try:
        source = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return {}
    source = re.sub(r"/\*.*?\*/", "", source, flags=re.DOTALL)
    source = re.sub(r"(^|\s)//.*$", r"\1", source, flags=re.MULTILINE)
    source = re.sub(r",\s*([}\]])", r"\1", source)
    try:
        value = json.loads(source)
    except json.JSONDecodeError:
        return {}
    return value if isinstance(value, dict) else {}


def _module_bases(root: Path, importer: str, module: str) -> Iterable[Path]:
    if module.startswith("."):
        yield (root / importer).parent / module
        return

    matched = False
    for config_name in ("tsconfig.json", "jsconfig.json"):
        config = _jsonc_object(root / config_name)
        compiler = config.get("compilerOptions")
        if not isinstance(compiler, dict):
            continue
        base_url = compiler.get("baseUrl", ".")
        base = root / (base_url if isinstance(base_url, str) else ".")
        paths = compiler.get("paths")
        if not isinstance(paths, dict):
            continue
        for pattern, replacements in paths.items():
            if not isinstance(pattern, str) or not isinstance(replacements, list):
                continue
            prefix, marker, suffix = pattern.partition("*")
            if marker:
                if not module.startswith(prefix) or not module.endswith(suffix):
                    continue
                wildcard = module[len(prefix):len(module) - len(suffix) if suffix else None]
            elif module == pattern:
                wildcard = ""
            else:
                continue
            for replacement in replacements:
                if isinstance(replacement, str):
                    matched = True
                    yield base / replacement.replace("*", wildcard)
    if not matched and module.startswith(("@/", "~/")):
        yield root / "src" / module[2:]


def _resolve_module(root: Path, importer: str, module: str) -> str:
    candidates: list[Path] = []
    for base in _module_bases(root, importer, module):
        candidates.append(base)
        candidates.extend(Path(str(base) + suffix) for suffix in RESOLUTION_EXTENSIONS)
        candidates.extend(base / ("index" + suffix) for suffix in RESOLUTION_EXTENSIONS)
    for candidate in candidates:
        try:
            resolved = candidate.resolve()
            resolved.relative_to(root.resolve())
        except (OSError, ValueError):
            continue
        if resolved.is_file() and resolved.suffix.lower() in SOURCE_EXTENSIONS:
            return resolved.relative_to(root.resolve()).as_posix()
    return ""


def _source_files(tree: Path) -> dict[str, str]:
    sources: dict[str, str] = {}
    for directory, names, files in os.walk(tree, topdown=True, followlinks=False):
        directory_path = Path(directory)
        relative_directory = directory_path.relative_to(tree).as_posix()
        prefix = "" if relative_directory == "." else relative_directory + "/"
        names[:] = sorted(
            name
            for name in names
            if not SOURCE_INDEX_EXCLUDE.search(prefix + name + "/")
            and not (directory_path / name).is_symlink()
        )
        for name in sorted(files):
            path = directory_path / name
            relative = prefix + name
            if path.is_symlink() or path.suffix.lower() not in SOURCE_EXTENSIONS:
                continue
            if SOURCE_INDEX_EXCLUDE.search(relative):
                continue
            try:
                sources[relative] = path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
    return sources


def _exported_declaration(
    tree: Path,
    declarations: dict[str, dict[str, Declaration]],
    sources: dict[str, str],
    source_file: str,
    imported_name: str,
    local_name: str,
    seen: set[tuple[str, str]] | None = None,
    trace: set[str] | None = None,
) -> Declaration | None:
    seen = set() if seen is None else seen
    trace = set() if trace is None else trace
    key = (source_file, imported_name)
    if not source_file or key in seen or len(seen) >= 12:
        return None
    seen.add(key)
    trace.add(source_file)
    if imported_name != "default":
        direct = declarations.get(source_file, {}).get(imported_name)
        if direct is not None:
            return direct
    source = sources.get(source_file, "")
    if imported_name == "default":
        identifier = DEFAULT_EXPORT_IDENTIFIER.search(source)
        if identifier:
            direct = declarations.get(source_file, {}).get(identifier.group(1))
            if direct is not None:
                return direct
        exported = DEFAULT_EXPORT.search(source)
        if exported:
            expression = _read_initializer(source, exported.end())
            return Declaration(
                file=source_file,
                name=local_name,
                expression=expression,
                line=source.count("\n", 0, exported.start()) + 1,
            )

    for match in NAMED_REEXPORT.finditer(source):
        module = match.group(2)
        for raw_binding in match.group(1).split(","):
            parts = re.split(r"\s+as\s+", raw_binding.strip(), maxsplit=1)
            original = parts[0].strip()
            exported_name = parts[-1].strip()
            if exported_name != imported_name:
                continue
            target = _resolve_module(tree, source_file, module)
            branch_trace = set(trace)
            resolved = _exported_declaration(
                tree,
                declarations,
                sources,
                target,
                original,
                local_name,
                seen,
                branch_trace,
            )
            if resolved is not None:
                trace.update(branch_trace)
                return resolved
    if imported_name != "default":
        for match in STAR_REEXPORT.finditer(source):
            target = _resolve_module(tree, source_file, match.group(1))
            branch_trace = set(trace)
            resolved = _exported_declaration(
                tree,
                declarations,
                sources,
                target,
                imported_name,
                local_name,
                seen,
                branch_trace,
            )
            if resolved is not None:
                trace.update(branch_trace)
                return resolved
    return None


def _symbol_declaration(
    tree: Path,
    declarations: dict[str, dict[str, Declaration]],
    sources: dict[str, str],
    source_file: str,
    symbol: str,
    trace: set[str] | None = None,
) -> Declaration | None:
    trace = set() if trace is None else trace
    direct = declarations.get(source_file, {}).get(symbol)
    if direct is not None:
        trace.add(source_file)
        return direct
    imported = _named_imports(sources.get(source_file, "")).get(symbol)
    if imported is None:
        return None
    module, imported_name = imported
    target = _resolve_module(tree, source_file, module)
    branch_trace = set(trace)
    resolved = _exported_declaration(
        tree,
        declarations,
        sources,
        target,
        imported_name,
        symbol,
        trace=branch_trace,
    )
    if resolved is not None:
        trace.update(branch_trace)
    return resolved


def _referenced_symbol(expression: str) -> str:
    match = re.match(r"\s*([A-Za-z_$][\w$]*)\s*(?:\?\.)?\.", expression)
    if match and match.group(1) not in {"Array", "Object", "Math", "JSON"}:
        return match.group(1)
    derived = re.match(
        r"\s*(?:useMemo|computed)\s*\(\s*(?:\([^)]*\)|[A-Za-z_$][\w$]*)"
        r"\s*=>\s*\(?\s*([A-Za-z_$][\w$]*)\s*(?:\?\.|\.|\[)",
        expression,
    )
    return derived.group(1) if derived else ""


def _bound_mock_reason(
    tree: Path,
    declarations: dict[str, dict[str, Declaration]],
    sources: dict[str, str],
    declaration: Declaration,
    seen: set[tuple[str, str]] | None = None,
    trace: set[str] | None = None,
) -> tuple[Declaration, str] | None:
    seen = set() if seen is None else seen
    trace = set() if trace is None else trace
    key = (declaration.file, declaration.name)
    if key in seen or len(seen) >= 12:
        return None
    seen.add(key)
    trace.add(declaration.file)
    reason = _mock_reason(declaration)
    if reason:
        return declaration, reason
    referenced = _referenced_symbol(declaration.expression)
    if not referenced:
        return None
    upstream = _symbol_declaration(
        tree, declarations, sources, declaration.file, referenced, trace,
    )
    if upstream is None:
        return None
    return _bound_mock_reason(tree, declarations, sources, upstream, seen, trace)


def _changed_digest(files: list[str], tree: Path) -> str:
    digest = hashlib.sha256()
    root = tree.resolve()
    for relative in sorted(set(files)):
        digest.update(relative.encode("utf-8", errors="surrogateescape"))
        digest.update(b"\0")
        path = tree / relative
        try:
            resolved = path.resolve()
            resolved.relative_to(root)
            if path.is_symlink():
                digest.update(b"symlink\0")
                digest.update(os.readlink(path).encode("utf-8", errors="surrogateescape"))
            elif path.is_file():
                digest.update(b"file\0")
                digest.update(hashlib.sha256(path.read_bytes()).digest())
            else:
                digest.update(b"missing\0")
        except (OSError, ValueError):
            digest.update(b"unreadable\0")
        digest.update(b"\0")
    return digest.hexdigest()


def scan(files: list[str], tree: Path) -> tuple[int, dict[str, object] | None]:
    """Return changed sources scanned and the first collection-bound hit."""

    changed = {
        relative
        for relative in files
        if Path(relative).suffix.lower() in SOURCE_EXTENSIONS
        and not SOURCE_INDEX_EXCLUDE.search(relative)
    }
    sources = _source_files(tree)
    scanned = sum(1 for relative in changed if relative in sources)
    declarations = {
        relative: _declarations(relative, source)
        for relative, source in sources.items()
    }

    for render_file, source in sources.items():
        if RENDER_EXCLUDE.search(render_file):
            continue
        rendered = _rendered_symbols(source)
        for local_name in sorted(rendered):
            resolution_trace = {render_file}
            declaration = _symbol_declaration(
                tree,
                declarations,
                sources,
                render_file,
                local_name,
                resolution_trace,
            )
            if declaration is None:
                continue
            bound = _bound_mock_reason(
                tree,
                declarations,
                sources,
                declaration,
                trace=resolution_trace,
            )
            if bound is None:
                continue
            backing, reason = bound
            if changed.isdisjoint(resolution_trace):
                continue
            return scanned, {
                "file": backing.file,
                "line": backing.line,
                "snippet": backing.name[:80],
                "reason": reason,
                "render_file": render_file,
            }

        if render_file in changed:
            structural = _mask_non_code(source)
            for match in DIRECT_INLINE_MAP.finditer(structural):
                body = source[match.start("body"):match.end("body")]
                call = _balanced_parenthesized(structural, match.end() - 1)
                operational_fields = len(OPERATIONAL_FIELD.findall(body)) >= 2
                strong_operational = STRONG_OPERATIONAL_FIELD.search(body) is not None
                static_content = STATIC_CONTENT_FIELD.search(body) is not None
                if JSX_TAG.search(call) and (
                    (operational_fields and strong_operational and not static_content)
                    or FAKER.search(body)
                    or PLACEHOLDER_VALUE.search(body)
                ):
                    return scanned, {
                        "file": render_file,
                        "line": source.count("\n", 0, match.start()) + 1,
                        "snippet": "inline array map",
                        "reason": "direct_inline_operational_collection",
                        "render_file": render_file,
                    }
    return scanned, None


def main() -> int:
    # Transport: stdin first, _NM_FILES as fallback. An env string is capped at
    # MAX_ARG_STRLEN (131071 bytes) on Linux, so a large changed-file list makes
    # execve fail with E2BIG -- the caller then captures its own
    # "INCONCLUSIVE:detector_error" fallback and the gate silently passes
    # through. macOS has no per-string cap, which is why that failure was
    # Linux-only. stdin has no such limit.
    # Read defensively: a caller may close stdin (sys.stdin is then None) or
    # hand over a tty. Either way fall back to the env var rather than raising,
    # because an uncaught error here reads to the caller as
    # "INCONCLUSIVE:detector_error" -- the exact silent pass-through this
    # transport change exists to remove.
    raw = ""
    try:
        if sys.stdin is not None and not sys.stdin.isatty():
            raw = sys.stdin.read()
    except (OSError, ValueError):
        raw = ""
    if not raw.strip():
        raw = os.environ.get("_NM_FILES", "")
    files = [line.strip() for line in raw.splitlines() if line.strip()]
    tree = Path(os.environ.get("_NM_TREE", ".")).resolve()
    output = os.environ.get("_NM_OUT", "")
    scanned, hit = scan(files, tree)
    receipt = {
        "schema_version": 2,
        "scanned": scanned,
        "hit": hit is not None,
        "file": hit["file"] if hit else "",
        "line": hit["line"] if hit else 0,
        "snippet": hit["snippet"] if hit else "",
        "reason": hit["reason"] if hit else "",
        "render_file": hit["render_file"] if hit else "",
        "base_sha": os.environ.get("_NM_BASE", ""),
        "source_digest": _changed_digest(files, tree),
    }
    if output:
        try:
            destination = Path(output)
            destination.parent.mkdir(parents=True, exist_ok=True)
            temporary = destination.with_name(destination.name + ".tmp")
            temporary.write_text(json.dumps(receipt, indent=2), encoding="utf-8")
            temporary.replace(destination)
        except OSError as error:
            print(f"receipt write failed: {error}", file=os.sys.stderr)
            return 2

    if hit:
        print(f"FAIL:{hit['file']}:{hit['line']}:{hit['snippet']}:{hit['reason']}")
    elif scanned == 0:
        print("SKIP:0")
    else:
        print(f"PASS:{scanned}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Emit the FIXED analytics allowlist from a finished proof.json as key=value
lines, one per line, for loki_emit_build_verified (autonomy/telemetry.sh).

This is the SINGLE authoritative allowlist for opt-in build-outcome analytics.
Only already-computed scalars are ever emitted -- never code, spec/PRD text,
paths, or file names. Anything not named here is never read, so a proof.json
schema change cannot silently start leaking a new field.

Free-text-shaped fields are excluded on purpose:
  - headline is a bounded enum (VERIFIED / VERIFIED WITH GAPS / NOT VERIFIED),
    computed deterministically from facts -- never spec/project text.
  - files_changed is emitted as a COUNT only, never the paths list.

Usage: proof-analytics-props.py <proof.json>
Fail-open: any error prints nothing and exits non-zero; the caller drops it.
"""
import json
import sys


def main():
    if len(sys.argv) < 2:
        return 1
    try:
        p = json.load(open(sys.argv[1]))
    except Exception:
        return 1

    honesty = p.get("honesty") or {}
    council = p.get("council") or {}
    facts = p.get("facts") or {}
    qg = p.get("quality_gates") or {}
    fc = p.get("files_changed") or {}

    gates_passed = qg.get("passed")
    gates_total = qg.get("total")
    try:
        rate = round(int(gates_passed) / int(gates_total), 3) if gates_total else None
    except Exception:
        rate = None

    out = {
        "headline": str(honesty.get("headline") or ""),  # bounded enum only
        "evidence_gate_verdict": str(
            honesty.get("evidence_gate_verdict")
            or (facts.get("evidence_gate") or {}).get("verdict")
            or ""
        ),
        "final_verdict": str(council.get("final_verdict") or ""),
        "iterations": p.get("iterations"),
        "files_changed_count": fc.get("count") if isinstance(fc, dict) else None,
        "wall_clock_sec": p.get("wall_clock_sec"),
        "gates_passed": gates_passed,
        "gates_total": gates_total,
        "gate_pass_rate": rate,
    }

    for k, v in out.items():
        if v is None or v == "":
            continue
        # key=value; sanitize so a value can never inject a second pair or a newline.
        v = str(v).replace("\n", " ").replace("=", "-")
        sys.stdout.write("%s=%s\n" % (k, v))
    return 0


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""Bind an immutable specification to a structured requirement verdict schema."""

from __future__ import annotations

import hashlib
import hmac
import json
import os
import re
import stat
import sys
from copy import deepcopy
from dataclasses import dataclass
from pathlib import Path


PRODUCT_QUALITY_CONTRACT_END = "--- END AUTONOMI PRODUCT QUALITY CONTRACT ---"
PRODUCT_QUALITY_REQUIREMENT_PREFIXES = (
    "Every visible control must perform its stated action.",
    "Do not ship dead forms,",
    "If the user explicitly requests no backend,",
    "Treat commercial claims as user-supplied,",
    "Label illustrative material in the interface and omit unsupported customer logos,",
    "Add or update at least one non-vacuous automated test for the critical path,",
)


@dataclass(frozen=True)
class Contract:
    specification: bytes
    manifest: dict[str, object]
    schema: dict[str, object]

    @property
    def manifest_bytes(self) -> bytes:
        return json.dumps(self.manifest, sort_keys=True).encode("utf-8")

    @property
    def schema_bytes(self) -> bytes:
        return json.dumps(self.schema, sort_keys=True).encode("utf-8")


MAX_REQUIREMENTS_PER_SHARD = 8


def _shard_path(shard_dir: Path, kind: str, index: int) -> Path:
    if kind not in {"manifest", "schema", "result"} or index < 1:
        raise ValueError("invalid_shard")
    suffix = "json" if kind in {"manifest", "schema"} else "txt"
    return shard_dir / f"{kind}-{index:03d}.{suffix}"


def _validate_shard_size(raw_size: str | int) -> int:
    text = str(raw_size)
    if re.fullmatch(r"[0-9]+", text) is None:
        raise ValueError("invalid_shard_size")
    size = int(text, 10)
    if not 1 <= size <= MAX_REQUIREMENTS_PER_SHARD:
        raise ValueError("invalid_shard_size")
    return size


def _safe_directory(path: Path) -> None:
    try:
        info = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("unsafe_shard_directory") from exc
    if (
        not stat.S_ISDIR(info.st_mode)
        or info.st_uid != os.getuid()
        or stat.S_IMODE(info.st_mode) != 0o700
    ):
        raise RuntimeError("unsafe_shard_directory")


def extract_requirement_units(text: str) -> list[str]:
    """Return deterministic acceptance units without interpreting product verbs."""
    units: list[str] = []
    paragraph: list[str] = []
    list_item: list[str] = []

    def flush_paragraph() -> None:
        if not paragraph:
            return
        joined = " ".join(paragraph)
        units.extend(
            part.strip()
            for part in re.split(r"(?<=[.!?])\s+(?=[A-Z0-9])", joined)
            if part.strip()
        )
        paragraph.clear()

    def flush_item() -> None:
        if list_item:
            units.append(" ".join(list_item))
            list_item.clear()

    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line:
            flush_item()
            flush_paragraph()
            continue
        heading = re.fullmatch(r"#{1,6}\s+(.+)", line)
        if heading:
            flush_item()
            flush_paragraph()
            units.append(heading.group(1).strip())
            continue
        item = re.match(
            r"^(?:[-*+]\s+(?:\[[ xX]\]\s*)?|\d+[.)]\s+)(.+)$", line
        )
        if item:
            flush_item()
            flush_paragraph()
            list_item.append(item.group(1).strip())
        elif list_item and raw_line[:1].isspace():
            list_item.append(line)
        else:
            flush_item()
            paragraph.append(line)
    flush_item()
    flush_paragraph()
    return units


def extract_bound_requirement_units(text: str) -> list[str]:
    """Extract the user brief when a platform quality policy precedes it."""
    if PRODUCT_QUALITY_CONTRACT_END in text:
        text = text.split(PRODUCT_QUALITY_CONTRACT_END, 1)[1].strip()
    return extract_requirement_units(text)


def extract_product_quality_requirement_units(text: str) -> list[str]:
    """Select the mandatory review rules from a wrapped product quality policy."""
    if PRODUCT_QUALITY_CONTRACT_END not in text:
        return []
    policy = text.split(PRODUCT_QUALITY_CONTRACT_END, 1)[0]
    units = extract_requirement_units(policy)
    selected: list[str] = []
    for prefix in PRODUCT_QUALITY_REQUIREMENT_PREFIXES:
        matches = [unit for unit in units if unit.startswith(prefix)]
        if len(matches) != 1:
            raise LookupError("incomplete_product_quality_contract")
        selected.append(matches[0])
    return selected


def _schema(spec_sha256: str, ids: list[str], count: int) -> dict[str, object]:
    return {
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "additionalProperties": False,
        "required": [
            "schema",
            "spec_sha256",
            "verdict",
            "requirements",
            "findings",
        ],
        "properties": {
            "schema": {"const": "loki-requirements-verdict/v1"},
            "spec_sha256": {"const": spec_sha256},
            "verdict": {"enum": ["PASS", "FAIL"]},
            "requirements": {
                "type": "array",
                "minItems": count,
                "maxItems": count,
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["id", "status", "evidence"],
                    "properties": {
                        "id": {"enum": ids},
                        "status": {"enum": ["PASS", "FAIL"]},
                        "evidence": {
                            "type": "string",
                            "minLength": 1,
                            "maxLength": 180,
                        },
                    },
                },
            },
            "findings": {
                "type": "array",
                "items": {
                    "type": "object",
                    "additionalProperties": False,
                    "required": ["severity", "description"],
                    "properties": {
                        "severity": {
                            "enum": ["Critical", "High", "Medium", "Low"]
                        },
                        "description": {
                            "type": "string",
                            "minLength": 1,
                            "maxLength": 320,
                        },
                    },
                },
            },
        },
    }


def _limit(raw_limit: str, hard_limit: int) -> int:
    if re.fullmatch(r"[0-9]+", raw_limit) is None:
        raise ValueError("invalid_limit")
    limit = int(raw_limit, 10)
    if not 1 <= limit <= hard_limit:
        raise ValueError("invalid_limit")
    return limit


def _read_regular(
    path: Path, maximum: int, *, exact_mode: int | None = None
) -> bytes:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    if hasattr(os, "O_CLOEXEC"):
        flags |= os.O_CLOEXEC
    try:
        descriptor = os.open(path, flags)
        info = os.fstat(descriptor)
        path_info = os.lstat(path)
        if (
            not stat.S_ISREG(info.st_mode)
            or not stat.S_ISREG(path_info.st_mode)
            or info.st_uid != os.getuid()
            or info.st_nlink != 1
            or (
                exact_mode is not None
                and stat.S_IMODE(info.st_mode) != exact_mode
            )
            or (info.st_dev, info.st_ino) != (path_info.st_dev, path_info.st_ino)
        ):
            raise RuntimeError("unsafe_file")
        content = bytearray()
        while len(content) <= maximum:
            chunk = os.read(descriptor, min(65_536, maximum + 1 - len(content)))
            if not chunk:
                break
            content.extend(chunk)
        final_info = os.fstat(descriptor)
        final_path_info = os.lstat(path)
        if (
            (info.st_dev, info.st_ino) != (final_info.st_dev, final_info.st_ino)
            or (info.st_dev, info.st_ino)
            != (final_path_info.st_dev, final_path_info.st_ino)
        ):
            raise RuntimeError("replaced_file")
    except OSError as exc:
        raise RuntimeError("unreadable") from exc
    finally:
        if "descriptor" in locals():
            os.close(descriptor)
    if len(content) > maximum:
        raise OverflowError(f"oversized:{len(content)}")
    return bytes(content)


def _path_identity(path: Path, *, exact_mode: int = 0o600) -> str:
    flags = os.O_RDONLY
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    if hasattr(os, "O_CLOEXEC"):
        flags |= os.O_CLOEXEC
    try:
        descriptor = os.open(path, flags)
        info = os.fstat(descriptor)
        path_info = os.lstat(path)
    except OSError as exc:
        raise RuntimeError("unreadable") from exc
    finally:
        if "descriptor" in locals():
            os.close(descriptor)
    if (
        not stat.S_ISREG(info.st_mode)
        or not stat.S_ISREG(path_info.st_mode)
        or info.st_uid != os.getuid()
        or info.st_nlink != 1
        or stat.S_IMODE(info.st_mode) != exact_mode
        or (info.st_dev, info.st_ino) != (path_info.st_dev, path_info.st_ino)
    ):
        raise RuntimeError("unsafe_file")
    return f"{info.st_dev}:{info.st_ino}"


def artifact_identity(*paths: Path) -> str:
    return ",".join(_path_identity(path) for path in paths)


def _write_new(path: Path, content: bytes) -> None:
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    if hasattr(os, "O_NOFOLLOW"):
        flags |= os.O_NOFOLLOW
    if hasattr(os, "O_CLOEXEC"):
        flags |= os.O_CLOEXEC
    try:
        descriptor = os.open(path, flags, 0o600)
        os.fchmod(descriptor, 0o600)
        view = memoryview(content)
        while view:
            written = os.write(descriptor, view)
            if written <= 0:
                raise OSError("short write")
            view = view[written:]
        info = os.fstat(descriptor)
        path_info = os.lstat(path)
        if (
            not stat.S_ISREG(info.st_mode)
            or info.st_uid != os.getuid()
            or stat.S_IMODE(info.st_mode) != 0o600
            or info.st_nlink != 1
            or (info.st_dev, info.st_ino) != (path_info.st_dev, path_info.st_ino)
        ):
            raise RuntimeError("unsafe_file")
    except FileExistsError:
        if not hmac.compare_digest(
            _read_regular(path, len(content), exact_mode=0o600), content
        ):
            raise RuntimeError("contract_mismatch")
        return
    except OSError as exc:
        raise RuntimeError("contract_write_failed") from exc
    finally:
        if "descriptor" in locals():
            os.close(descriptor)


def publish_bound(stage: Path, destination: Path, maximum: int) -> str:
    """Publish one validated staged result after its producer has quiesced."""
    content = _read_regular(stage, maximum)
    if not content:
        raise RuntimeError("empty_file")
    try:
        destination_info = os.lstat(destination)
    except FileNotFoundError:
        destination_info = None
    if destination_info is not None:
        if stat.S_ISDIR(destination_info.st_mode):
            raise RuntimeError("unsafe_destination")
        os.unlink(destination)
    os.replace(stage, destination)
    published = _read_regular(destination, maximum)
    if not hmac.compare_digest(content, published):
        raise RuntimeError("publish_mismatch")
    return (
        hashlib.sha256(published).hexdigest()
        + "|"
        + _path_identity(destination)
    )


def derive_contract(
    source: Path,
    expected_sha256: str,
    raw_limit: str,
    hard_limit: int,
) -> Contract:
    limit = _limit(raw_limit, hard_limit)
    content = _read_regular(source, limit)
    actual_sha256 = hashlib.sha256(content).hexdigest()
    if not hmac.compare_digest(actual_sha256, expected_sha256):
        raise PermissionError("hash_mismatch")
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise UnicodeError("invalid_utf8") from exc
    units = extract_bound_requirement_units(text)
    quality_units = extract_product_quality_requirement_units(text)
    if not units:
        raise LookupError("no_requirements")
    requirements = [
        {
            "id": f"R{index:03d}",
            "text": unit,
            "sha256": hashlib.sha256(unit.encode("utf-8")).hexdigest(),
        }
        for index, unit in enumerate(units, 1)
    ]
    requirements.extend(
        {
            "id": f"Q{index:03d}",
            "text": unit,
            "sha256": hashlib.sha256(unit.encode("utf-8")).hexdigest(),
        }
        for index, unit in enumerate(quality_units, 1)
    )
    manifest = {
        "schema": "loki-requirements-manifest/v1",
        "spec_sha256": actual_sha256,
        "requirements": requirements,
    }
    return Contract(
        specification=content,
        manifest=manifest,
        schema=_schema(
            actual_sha256,
            [item["id"] for item in requirements],
            len(requirements),
        ),
    )


def derive_shards(contract: Contract, raw_size: str | int) -> list[Contract]:
    """Split one verified contract into deterministic balanced contiguous shards."""
    maximum = _validate_shard_size(raw_size)
    requirements = contract.manifest.get("requirements")
    if not isinstance(requirements, list) or not requirements:
        raise RuntimeError("invalid_full_contract")
    total = len(requirements)
    shard_count = (total + maximum - 1) // maximum
    base_size, extra = divmod(total, shard_count)
    full_manifest_sha256 = hashlib.sha256(contract.manifest_bytes).hexdigest()
    shards: list[Contract] = []
    offset = 0
    for zero_index in range(shard_count):
        shard_size = base_size + (1 if zero_index < extra else 0)
        selected = deepcopy(requirements[offset : offset + shard_size])
        ids = [item.get("id") for item in selected if isinstance(item, dict)]
        if len(ids) != shard_size or any(not isinstance(item, str) for item in ids):
            raise RuntimeError("invalid_full_contract")
        manifest = {
            "schema": "loki-requirements-manifest/v1",
            "spec_sha256": contract.manifest["spec_sha256"],
            "requirements": selected,
            "shard": {
                "schema": "loki-requirements-shard/v1",
                "index": zero_index + 1,
                "count": shard_count,
                "max_requirements": maximum,
                "requirement_offset": offset,
                "full_requirement_count": total,
                "full_manifest_sha256": full_manifest_sha256,
            },
        }
        shards.append(
            Contract(
                specification=contract.specification,
                manifest=manifest,
                schema=_schema(contract.manifest["spec_sha256"], ids, shard_size),
            )
        )
        offset += shard_size
    if offset != total:
        raise RuntimeError("incomplete_shards")
    return shards


def write_shards(
    contract: Contract,
    raw_size: str,
    shard_dir: Path,
) -> dict[str, object]:
    _safe_directory(shard_dir)
    shards = derive_shards(contract, raw_size)
    identities: list[str] = []
    sizes: list[int] = []
    for index, shard in enumerate(shards, 1):
        manifest_path = _shard_path(shard_dir, "manifest", index)
        schema_path = _shard_path(shard_dir, "schema", index)
        _write_new(manifest_path, shard.manifest_bytes)
        _write_new(schema_path, shard.schema_bytes)
        identities.append(artifact_identity(manifest_path, schema_path))
        sizes.append(len(shard.manifest["requirements"]))
    return {
        "schema": "loki-requirements-shards/v1",
        "count": len(shards),
        "max_requirements": _validate_shard_size(raw_size),
        "sizes": sizes,
        "identities": identities,
        "full_manifest_sha256": hashlib.sha256(contract.manifest_bytes).hexdigest(),
    }


def verify_shard(
    contract: Contract,
    raw_size: str,
    shard_dir: Path,
    index: int,
    expected_identity: str = "",
) -> Contract:
    _safe_directory(shard_dir)
    shards = derive_shards(contract, raw_size)
    if index < 1 or index > len(shards):
        raise ValueError("invalid_shard")
    shard = shards[index - 1]
    manifest_path = _shard_path(shard_dir, "manifest", index)
    schema_path = _shard_path(shard_dir, "schema", index)
    for path, expected in (
        (manifest_path, shard.manifest_bytes),
        (schema_path, shard.schema_bytes),
    ):
        actual = _read_regular(path, len(expected), exact_mode=0o600)
        if not hmac.compare_digest(actual, expected):
            raise RuntimeError("shard_contract_mismatch")
    actual_identity = artifact_identity(manifest_path, schema_path)
    if expected_identity and not hmac.compare_digest(
        actual_identity, expected_identity
    ):
        raise RuntimeError("shard_contract_replaced")
    return shard


def _decode_json_list(raw: str, expected_count: int) -> list[str]:
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as exc:
        raise ValueError("invalid_binding_list") from exc
    if (
        not isinstance(value, list)
        or len(value) != expected_count
        or not all(isinstance(item, str) and item for item in value)
    ):
        raise ValueError("invalid_binding_list")
    return value


def _read_bound_result(path: Path, binding: str, maximum: int) -> bytes:
    try:
        expected_sha256, expected_identity = binding.split("|", 1)
    except ValueError as exc:
        raise ValueError("invalid_result_binding") from exc
    if re.fullmatch(r"[0-9a-f]{64}", expected_sha256) is None:
        raise ValueError("invalid_result_binding")
    content = _read_regular(path, maximum, exact_mode=0o600)
    if not hmac.compare_digest(hashlib.sha256(content).hexdigest(), expected_sha256):
        raise RuntimeError("result_mismatch")
    if not hmac.compare_digest(_path_identity(path), expected_identity):
        raise RuntimeError("result_replaced")
    return content


def _parse_legacy_result(content: bytes) -> tuple[str, list[str]]:
    try:
        text = content.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise ValueError("invalid_result") from exc
    lines = text.splitlines()
    if (
        len(lines) < 3
        or lines[0] not in {"VERDICT: PASS", "VERDICT: FAIL"}
        or lines[1] != "FINDINGS:"
        or any(not line.startswith("- ") or len(line) <= 2 for line in lines[2:])
    ):
        raise ValueError("invalid_result")
    findings = lines[2:]
    if "- None" in findings and findings != ["- None"]:
        raise ValueError("invalid_result")
    verdict = lines[0].removeprefix("VERDICT: ")
    if verdict == "PASS" and findings != ["- None"]:
        raise ValueError("invalid_result")
    return verdict, findings


def synthesize_shards(
    contract: Contract,
    raw_size: str,
    shard_dir: Path,
    contract_identities_json: str,
    result_bindings_json: str,
    maximum: int,
    destination: Path,
) -> str:
    """Create one logical verdict only after every exact shard result is bound."""
    shards = derive_shards(contract, raw_size)
    contract_identities = _decode_json_list(
        contract_identities_json, len(shards)
    )
    result_bindings = _decode_json_list(result_bindings_json, len(shards))
    verdicts: list[str] = []
    findings: list[str] = []
    for index, (contract_identity, result_binding) in enumerate(
        zip(contract_identities, result_bindings, strict=True), 1
    ):
        verify_shard(contract, raw_size, shard_dir, index, contract_identity)
        result_path = _shard_path(shard_dir, "result", index)
        verdict, shard_findings = _parse_legacy_result(
            _read_bound_result(result_path, result_binding, maximum)
        )
        verdicts.append(verdict)
        if shard_findings != ["- None"]:
            findings.extend(shard_findings)
    logical_verdict = "PASS" if all(item == "PASS" for item in verdicts) else "FAIL"
    logical_findings = findings or ["- None"]
    logical = (
        "VERDICT: "
        + logical_verdict
        + "\nFINDINGS:\n"
        + "\n".join(logical_findings)
        + "\n"
    ).encode("utf-8")
    _write_new(destination, logical)
    return hashlib.sha256(logical).hexdigest() + "|" + _path_identity(destination)


def synthesize_failed_shard(
    contract: Contract,
    raw_size: str,
    shard_dir: Path,
    index: int,
    contract_identity: str,
    result_binding: str,
    maximum: int,
    destination: Path,
) -> str:
    """Publish one exact valid FAIL without waiting for irrelevant PASS shards."""
    verify_shard(contract, raw_size, shard_dir, index, contract_identity)
    content = _read_bound_result(
        _shard_path(shard_dir, "result", index), result_binding, maximum
    )
    verdict, _ = _parse_legacy_result(content)
    if verdict != "FAIL":
        raise RuntimeError("shard_did_not_fail")
    _write_new(destination, content)
    return hashlib.sha256(content).hexdigest() + "|" + _path_identity(destination)


def verify_contract(
    source: Path,
    snapshot: Path,
    expected_sha256: str,
    raw_limit: str,
    hard_limit: int,
    manifest_path: Path,
    schema_path: Path,
    expected_identity: str = "",
) -> Contract:
    contract = derive_contract(source, expected_sha256, raw_limit, hard_limit)
    for path, expected in (
        (snapshot, contract.specification),
        (manifest_path, contract.manifest_bytes),
        (schema_path, contract.schema_bytes),
    ):
        actual = _read_regular(path, len(expected), exact_mode=0o600)
        if not hmac.compare_digest(actual, expected):
            raise RuntimeError("contract_mismatch")
    actual_identity = artifact_identity(snapshot, manifest_path, schema_path)
    if expected_identity and not hmac.compare_digest(
        actual_identity, expected_identity
    ):
        raise RuntimeError("contract_replaced")
    return contract


def write_contract(
    source: Path,
    snapshot: Path,
    expected_sha256: str,
    raw_limit: str,
    hard_limit: int,
    manifest_path: Path,
    schema_path: Path,
) -> str:
    contract = derive_contract(source, expected_sha256, raw_limit, hard_limit)
    try:
        _write_new(snapshot, contract.specification)
        _write_new(manifest_path, contract.manifest_bytes)
        _write_new(schema_path, contract.schema_bytes)
    except RuntimeError:
        raise
    return f"ok:{len(contract.specification)}"


def _emit(contract: Contract, kind: str) -> None:
    if kind == "snapshot":
        sys.stdout.buffer.write(contract.specification)
    elif kind == "manifest":
        sys.stdout.buffer.write(contract.manifest_bytes)
    elif kind == "schema":
        sys.stdout.buffer.write(contract.schema_bytes)
    elif kind == "prompt":
        sys.stdout.write(
            json.dumps(
                {
                    "manifest": contract.manifest,
                    "schema": contract.schema,
                    "specification": contract.specification.decode("utf-8"),
                },
                sort_keys=True,
            )
        )
    elif kind != "none":
        raise ValueError("invalid_emit")


def main(argv: list[str]) -> int:
    try:
        if len(argv) == 5 and argv[1] == "publish-bound":
            maximum = _limit(argv[4], int(argv[4]))
            sys.stdout.write(
                publish_bound(Path(argv[2]), Path(argv[3]), maximum)
            )
        elif len(argv) in (10, 11) and argv[1] == "verify":
            contract = verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
                argv[10] if len(argv) == 11 else "",
            )
            _emit(contract, argv[9])
        elif len(argv) == 9 and argv[1] == "bind":
            verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
            )
            sys.stdout.write(
                artifact_identity(Path(argv[3]), Path(argv[7]), Path(argv[8]))
            )
        elif len(argv) in (5, 6) and argv[1] == "read-bound":
            maximum = _limit(argv[4], int(argv[4]))
            content = _read_regular(Path(argv[2]), maximum, exact_mode=0o600)
            if not hmac.compare_digest(hashlib.sha256(content).hexdigest(), argv[3]):
                raise PermissionError("hash_mismatch")
            if len(argv) == 6 and not hmac.compare_digest(
                _path_identity(Path(argv[2])), argv[5]
            ):
                raise RuntimeError("replaced_file")
            sys.stdout.buffer.write(content)
        elif len(argv) == 12 and argv[1] == "write-shards":
            contract = verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
                argv[9],
            )
            sys.stdout.write(
                json.dumps(
                    write_shards(contract, argv[10], Path(argv[11])),
                    sort_keys=True,
                )
            )
        elif len(argv) == 15 and argv[1] == "verify-shard":
            contract = verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
                argv[9],
            )
            shard = verify_shard(
                contract,
                argv[10],
                Path(argv[11]),
                int(argv[12]),
                argv[14],
            )
            _emit(shard, argv[13])
        elif len(argv) == 16 and argv[1] == "synthesize-shards":
            contract = verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
                argv[9],
            )
            maximum = _limit(argv[14], int(argv[14]))
            sys.stdout.write(
                synthesize_shards(
                    contract,
                    argv[10],
                    Path(argv[11]),
                    argv[12],
                    argv[13],
                    maximum,
                    Path(argv[15]),
                )
            )
        elif len(argv) == 17 and argv[1] == "synthesize-fail":
            contract = verify_contract(
                Path(argv[2]),
                Path(argv[3]),
                argv[4],
                argv[5],
                int(argv[6]),
                Path(argv[7]),
                Path(argv[8]),
                argv[9],
            )
            maximum = _limit(argv[15], int(argv[15]))
            sys.stdout.write(
                synthesize_failed_shard(
                    contract,
                    argv[10],
                    Path(argv[11]),
                    int(argv[12]),
                    argv[13],
                    argv[14],
                    maximum,
                    Path(argv[16]),
                )
            )
        elif len(argv) == 8:
            print(
                write_contract(
                    Path(argv[1]),
                    Path(argv[2]),
                    argv[3],
                    argv[4],
                    int(argv[5]),
                    Path(argv[6]),
                    Path(argv[7]),
                )
            )
        else:
            return 9
        return 0
    except OverflowError as exc:
        print(str(exc))
        return 4
    except PermissionError:
        print("hash_mismatch")
        return 5
    except UnicodeError as exc:
        print(str(exc))
        return 9
    except ValueError:
        print("invalid_limit")
        return 2
    except (OSError, RuntimeError, LookupError) as exc:
        print(str(exc))
        return 9


if __name__ == "__main__":
    raise SystemExit(main(sys.argv))

#!/usr/bin/env python3
"""Deterministic digest of the source tree verified by a Loki proof."""

from __future__ import annotations

import hashlib
import json
import os
import stat
import subprocess
from pathlib import Path
from typing import Any


MANIFEST_VERSION = 3
_EXCLUDED_TOP_LEVEL = {".git", ".loki"}
_EXCLUDED_TOP_LEVEL_GENERATED = {".next", ".nuxt", "target"}
_EXCLUDED_WALK_DIRS = {
    ".git",
    ".mypy_cache",
    ".pytest_cache",
    ".venv",
    "__pycache__",
    "node_modules",
    "venv",
}


def _sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def _git_paths(root: Path) -> list[str] | None:
    """Return tracked paths, or None when root is not the repository root."""
    try:
        inside = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "--is-inside-work-tree"],
            capture_output=True,
            timeout=10,
        )
        if inside.returncode != 0 or inside.stdout.strip() != b"true":
            return None
        top = subprocess.run(
            ["git", "-C", str(root), "rev-parse", "--show-toplevel"],
            capture_output=True,
            timeout=10,
        )
        if top.returncode != 0:
            return None
        top_path = Path(os.fsdecode(top.stdout.rstrip(b"\n"))).resolve()
        if top_path != root.resolve():
            return None
        result = subprocess.run(
            [
                "git",
                "-C",
                str(root),
                "ls-files",
                "-z",
                "--cached",
            ],
            capture_output=True,
            timeout=30,
        )
    except (OSError, subprocess.SubprocessError):
        return None
    if result.returncode != 0:
        return None
    return [
        raw.decode("utf-8", errors="surrogateescape")
        for raw in result.stdout.split(b"\0")
        if raw
    ]


def _filesystem_paths(root: Path, gitlinks: set[str]) -> list[str]:
    """Enumerate nondependency worktree bytes without consulting Git ignores."""
    paths: list[str] = []

    def visit(directory: Path, prefix: str) -> None:
        try:
            entries = sorted(os.scandir(directory), key=lambda item: item.name)
        except OSError:
            return
        for entry in entries:
            relative = f"{prefix}/{entry.name}" if prefix else entry.name
            normalized = relative.replace(os.sep, "/")
            if not prefix and entry.name in (
                _EXCLUDED_TOP_LEVEL | _EXCLUDED_TOP_LEVEL_GENERATED
            ):
                continue
            if normalized in gitlinks:
                paths.append(relative)
                continue
            try:
                is_directory = entry.is_dir(follow_symlinks=False)
            except OSError:
                paths.append(relative)
                continue
            if is_directory:
                if entry.name in _EXCLUDED_WALK_DIRS:
                    continue
                visit(Path(entry.path), relative)
            else:
                paths.append(relative)

    visit(root, "")
    return paths


def _gitlinks(root: Path) -> dict[str, list[dict[str, str]]]:
    """Return staged gitlink identities keyed by their repository path."""
    try:
        result = subprocess.run(
            ["git", "-C", str(root), "ls-files", "--stage", "-z"],
            capture_output=True,
            timeout=30,
        )
    except (OSError, subprocess.SubprocessError):
        return {}
    if result.returncode != 0:
        return {}
    links: dict[str, list[dict[str, str]]] = {}
    for record in result.stdout.split(b"\0"):
        if not record or b"\t" not in record:
            continue
        metadata, raw_path = record.split(b"\t", 1)
        fields = metadata.split()
        if len(fields) != 3 or fields[0] != b"160000":
            continue
        relative = raw_path.decode("utf-8", errors="surrogateescape")
        links.setdefault(relative, []).append(
            {
                "stage": fields[2].decode("ascii", errors="replace"),
                "oid": fields[1].decode("ascii", errors="replace"),
            }
        )
    for values in links.values():
        values.sort(key=lambda item: (item["stage"], item["oid"]))
    return links


def _gitlink_entry(
    root: Path, relative: str, index_entries: list[dict[str, str]]
) -> dict[str, Any]:
    """Bind both the staged gitlink and the checked-out submodule contents."""
    normalized = relative.replace(os.sep, "/")
    path = root / relative
    head_oid = ""
    try:
        head = subprocess.run(
            ["git", "-C", str(path), "rev-parse", "--verify", "HEAD"],
            capture_output=True,
            text=True,
            timeout=10,
        )
        if head.returncode == 0:
            head_oid = (head.stdout or "").strip()
    except (OSError, subprocess.SubprocessError):
        pass
    return {
        "path": normalized,
        "kind": "gitlink",
        "index": index_entries,
        "head_oid": head_oid,
        "worktree_sha256": compute_tree_digest(path),
    }


def _entry(
    root: Path,
    relative: str,
    gitlink_entries: list[dict[str, str]] | None = None,
) -> dict[str, Any] | None:
    normalized = relative.replace(os.sep, "/")
    top = normalized.split("/", 1)[0]
    if top in _EXCLUDED_TOP_LEVEL:
        return None
    if gitlink_entries is not None:
        return _gitlink_entry(root, relative, gitlink_entries)

    path = root / relative
    try:
        info = path.lstat()
    except FileNotFoundError:
        return {"path": normalized, "kind": "missing"}
    except OSError:
        return {"path": normalized, "kind": "unreadable"}

    executable = bool(info.st_mode & (stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH))
    if stat.S_ISLNK(info.st_mode):
        try:
            target = os.readlink(path)
        except OSError:
            target = ""
        target_bytes = os.fsencode(target)
        return {
            "path": normalized,
            "kind": "symlink",
            "executable": executable,
            "size": len(target_bytes),
            "sha256": hashlib.sha256(target_bytes).hexdigest(),
        }
    if stat.S_ISREG(info.st_mode):
        try:
            content_hash = _sha256_file(path)
        except OSError:
            return {"path": normalized, "kind": "unreadable"}
        return {
            "path": normalized,
            "kind": "file",
            "executable": executable,
            "size": info.st_size,
            "sha256": content_hash,
        }
    return {
        "path": normalized,
        "kind": "other",
        "executable": executable,
        "size": info.st_size,
    }


def build_manifest(root: str | os.PathLike[str]) -> dict[str, Any] | None:
    """Build the canonical Git worktree manifest used by proof binding."""
    resolved = Path(root).resolve()
    tracked_paths = _git_paths(resolved)
    if tracked_paths is None:
        return None
    gitlinks = _gitlinks(resolved)
    paths = set(tracked_paths)
    paths.update(_filesystem_paths(resolved, set(gitlinks)))
    entries = []
    for relative in sorted(paths):
        item = _entry(resolved, relative, gitlinks.get(relative))
        if item is not None:
            entries.append(item)
    return {
        "version": MANIFEST_VERSION,
        "filesystem_walk_excluded_top_level_directories": sorted(
            _EXCLUDED_TOP_LEVEL | _EXCLUDED_TOP_LEVEL_GENERATED
        ),
        "excluded_walk_directories": sorted(_EXCLUDED_WALK_DIRS),
        "entries": entries,
    }


def compute_tree_digest(root: str | os.PathLike[str]) -> str:
    """Return a SHA-256 digest, or an empty string when it cannot be derived."""
    manifest = build_manifest(root)
    if manifest is None:
        return ""
    encoded = json.dumps(
        manifest,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


__all__ = ["MANIFEST_VERSION", "build_manifest", "compute_tree_digest"]

#!/usr/bin/env python3
"""R4 trust trajectory - derive a per-project trust trend from proof-of-run history.

The story no competitor tells: show whether the agent is EARNING autonomy on
THIS repo over time. We derive the trajectory from the persistent per-run
records that R1/R3 already write to .loki/proofs/<run_id>/proof.json. No new
run-time instrumentation; this is a pure read-and-aggregate layer.

Axes (each derived from fields already present in proof.json):
  council_pass_rate   higher is better  (council.final_verdict approve => 1.0)
  gate_pass_rate      higher is better  (quality_gates.passed / .total)
  iterations          lower is better   (iterations.count)
  interventions       lower is better   (best-effort; available only when a
                                         proof carries it; never fabricated)

Honest-data rule: with fewer than 2 runs the trajectory is "insufficient"
(insufficient=True) and no direction is invented. Numbers are only ever derived
from real proof.json values; a missing axis is reported available=False, not 0.

Direction (up/down/flat) is computed by a median half-split: mean of the later
half minus mean of the earlier half. Robust to one noisy run, no float
regression needed, and a 2-run series degrades to last-vs-first.

Public API:
  compute_trajectory(loki_dir) -> dict   (schema_version 1)
  format_trajectory_human(traj) -> str
  format_trajectory_json(traj) -> str
  write_trajectory_cache(loki_dir, traj) -> str | None
  main(argv) -> int                      (CLI entry: prints human or --json)

No external deps. Python 3.8+ (matches the rest of autonomy/lib).
"""

import json
import os
import sys
from datetime import datetime, timezone

SCHEMA_VERSION = 1

# Per-axis "good direction" polarity. True => higher is better.
_AXIS_HIGHER_IS_BETTER = {
    "council_pass_rate": True,
    "gate_pass_rate": True,
    "iterations": False,
    "interventions": False,
}

# Per-axis flat epsilon. Rates live in [0,1]; counts use a larger band.
_AXIS_EPSILON = {
    "council_pass_rate": 0.01,
    "gate_pass_rate": 0.01,
    "iterations": 0.25,
    "interventions": 0.25,
}

_AXIS_LABELS = {
    "council_pass_rate": "Council pass rate",
    "gate_pass_rate": "Gate pass rate",
    "iterations": "Iterations to completion",
    "interventions": "Human interventions",
}

# Verdict tokens that count as a council pass.
_PASS_TOKENS = ("APPROVE", "APPROVED", "COMPLETE", "PASS", "PASSED")


def _read_json(path, default=None):
    try:
        with open(path, "r", encoding="utf-8") as fh:
            return json.load(fh)
    except Exception:
        return default


def _obj(v):
    return v if isinstance(v, dict) else {}


def _verdict_is_pass(verdict):
    """Map a council final_verdict string to a pass (True) / fail (False)."""
    v = str(verdict or "").strip().upper()
    if not v:
        return None
    for tok in _PASS_TOKENS:
        if v.startswith(tok):
            return True
    return False


def _council_pass_value(council):
    """Per-run council pass as 1.0 / 0.0, or None when no council signal."""
    council = _obj(council)
    # Primary: explicit final verdict.
    fv = _verdict_is_pass(council.get("final_verdict"))
    if fv is not None:
        return 1.0 if fv else 0.0
    # Secondary: reviewer roll-up. A run "passes" when every reviewer approved.
    reviewers = council.get("reviewers")
    if isinstance(reviewers, list) and reviewers:
        approve = 0
        counted = 0
        for r in reviewers:
            if not isinstance(r, dict):
                continue
            counted += 1
            vote = str(r.get("vote") or "").strip().upper()
            if any(vote.startswith(tok) for tok in _PASS_TOKENS):
                approve += 1
        if counted:
            return 1.0 if approve == counted else 0.0
    return None


def _gate_rate_value(quality_gates):
    """Per-run gate pass-rate in [0,1], or None when no gates recorded."""
    qg = _obj(quality_gates)
    total = qg.get("total")
    passed = qg.get("passed")
    try:
        total = int(total)
        passed = int(passed)
    except (TypeError, ValueError):
        return None
    if total <= 0:
        return None
    return max(0.0, min(1.0, passed / total))


def _iterations_value(iterations):
    """Per-run iteration count, or None when not recorded."""
    if isinstance(iterations, dict):
        c = iterations.get("count")
    else:
        c = iterations
    try:
        c = int(c)
    except (TypeError, ValueError):
        return None
    if c < 0:
        return None
    return float(c)


def _interventions_value(proof):
    """Per-run human-intervention count, ONLY when the proof carries it.

    There is no per-run intervention counter persisted today; we read it
    opportunistically so the axis lights up the moment that field exists, but
    we never fabricate a value. Returns None when absent.
    """
    council = _obj(proof.get("council"))
    for src in (council.get("interventions"), proof.get("interventions")):
        try:
            n = int(src)
        except (TypeError, ValueError):
            continue
        if n >= 0:
            return float(n)
    return None


def _load_runs(loki_dir):
    """Read every .loki/proofs/<id>/proof.json into a time-ordered run list."""
    proofs_dir = os.path.join(loki_dir, "proofs")
    runs = []
    try:
        entries = sorted(os.listdir(proofs_dir))
    except (OSError, FileNotFoundError):
        return runs
    for name in entries:
        d = os.path.join(proofs_dir, name)
        if not os.path.isdir(d):
            continue
        proof = _read_json(os.path.join(d, "proof.json"), default=None)
        if not isinstance(proof, dict):
            # Malformed / partial proof: skip, do not fail the trajectory.
            continue
        runs.append({
            "run_id": str(proof.get("run_id") or name),
            "generated_at": proof.get("generated_at"),
            "council_pass_rate": _council_pass_value(proof.get("council")),
            "gate_pass_rate": _gate_rate_value(proof.get("quality_gates")),
            "iterations": _iterations_value(proof.get("iterations")),
            "interventions": _interventions_value(proof),
        })
    # Order by generated_at ascending; runs without a timestamp sort last but
    # keep stable directory order among themselves.
    runs.sort(key=lambda r: (r.get("generated_at") is None, r.get("generated_at") or ""))
    return runs


def _mean(values):
    return sum(values) / len(values) if values else None


def _direction_for_axis(axis, ordered_values):
    """Compute direction for one axis over the time-ordered non-null values.

    Returns a dict describing the axis trend, or available=False when there is
    not enough non-null data (fewer than 2 points) to state a direction.
    """
    higher_is_better = _AXIS_HIGHER_IS_BETTER[axis]
    eps = _AXIS_EPSILON[axis]
    pts = [v for v in ordered_values if v is not None]
    n = len(pts)
    if n == 0:
        return {
            "axis": axis,
            "label": _AXIS_LABELS[axis],
            "available": False,
            "higher_is_better": higher_is_better,
            "note": "no runs recorded this metric",
        }
    if n < 2:
        return {
            "axis": axis,
            "label": _AXIS_LABELS[axis],
            "available": True,
            "data_points": n,
            "latest": round(pts[-1], 4),
            "higher_is_better": higher_is_better,
            "direction": "flat",
            "improving": None,
            "delta": 0.0,
            "earlier_mean": round(pts[0], 4),
            "later_mean": round(pts[-1], 4),
            "insufficient": True,
            "note": "not enough history yet (need 2+ runs with this metric)",
        }
    # Median half-split. Odd count drops the middle so halves never overlap.
    half = n // 2
    earlier = pts[:half]
    later = pts[n - half:]
    earlier_mean = _mean(earlier)
    later_mean = _mean(later)
    delta = later_mean - earlier_mean
    if abs(delta) <= eps:
        direction = "flat"
    elif delta > 0:
        direction = "up"
    else:
        direction = "down"
    if direction == "flat":
        improving = None
    else:
        going_up = direction == "up"
        improving = (going_up == higher_is_better)
    return {
        "axis": axis,
        "label": _AXIS_LABELS[axis],
        "available": True,
        "data_points": n,
        "latest": round(pts[-1], 4),
        "higher_is_better": higher_is_better,
        "direction": direction,
        "improving": improving,
        "delta": round(delta, 4),
        "earlier_mean": round(earlier_mean, 4),
        "later_mean": round(later_mean, 4),
        "insufficient": False,
    }


def compute_trajectory(loki_dir):
    """Return the R4 trust trajectory snapshot for a project's .loki dir."""
    runs = _load_runs(loki_dir)
    axes_order = ["council_pass_rate", "gate_pass_rate", "iterations", "interventions"]

    series = []
    for r in runs:
        series.append({
            "run_id": r["run_id"],
            "generated_at": r["generated_at"],
            "council_pass_rate": r["council_pass_rate"],
            "gate_pass_rate": r["gate_pass_rate"],
            "iterations": r["iterations"],
            "interventions": r["interventions"],
        })

    axes = {}
    for axis in axes_order:
        axes[axis] = _direction_for_axis(axis, [r[axis] for r in runs])

    insufficient = len(runs) < 2
    improving_axes = [
        a for a in axes_order
        if axes[a].get("available") and axes[a].get("improving") is True
    ]
    regressing_axes = [
        a for a in axes_order
        if axes[a].get("available") and axes[a].get("improving") is False
    ]

    notes = []
    if insufficient:
        notes.append(
            "not enough history yet: %d run(s) recorded, need 2+ to show a trend"
            % len(runs)
        )
    if not axes["interventions"].get("available"):
        notes.append(
            "intervention trend unavailable: no per-run intervention count in "
            "proof.json yet (axis lights up automatically once recorded)"
        )

    return {
        "schema_version": SCHEMA_VERSION,
        "generated_at": datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        "loki_dir": loki_dir,
        "runs_count": len(runs),
        "insufficient": insufficient,
        "axes": axes,
        "improving_count": len(improving_axes),
        "regressing_count": len(regressing_axes),
        "improving_axes": improving_axes,
        "regressing_axes": regressing_axes,
        "series": series,
        "notes": notes,
    }


def write_trajectory_cache(loki_dir, traj):
    """Persist the derived trajectory to .loki/metrics/trust-trajectory.json.

    Best-effort: returns the path on success, None on failure. This is a cache,
    always recomputable from .loki/proofs/; failure to write is non-fatal.
    """
    out_dir = os.path.join(loki_dir, "metrics")
    out_path = os.path.join(out_dir, "trust-trajectory.json")
    try:
        os.makedirs(out_dir, exist_ok=True)
        with open(out_path, "w", encoding="utf-8") as fh:
            json.dump(traj, fh, indent=2)
        return out_path
    except Exception:
        return None


def format_trajectory_json(traj):
    return json.dumps(traj, indent=2)


def _arrow(direction):
    return {"up": "up", "down": "down", "flat": "flat"}.get(direction, "?")


def _fmt_axis_line(ax):
    label = ax.get("label", ax.get("axis", "?"))
    if not ax.get("available"):
        return "  %-26s %s" % (label + ":", "no data")
    direction = ax.get("direction", "flat")
    latest = ax.get("latest")
    higher = ax.get("higher_is_better")
    if ax.get("insufficient"):
        tag = "(need 2+ runs)"
    elif ax.get("improving") is True:
        tag = "improving"
    elif ax.get("improving") is False:
        tag = "regressing"
    else:
        tag = "stable"
    polarity = "higher better" if higher else "lower better"
    return "  %-26s %-5s latest=%-7s %-11s [%s]" % (
        label + ":", _arrow(direction), latest, tag, polarity,
    )


def format_trajectory_human(traj):
    lines = []
    lines.append("Loki Mode Trust Trajectory  (snapshot at %s)" % traj.get("generated_at"))
    lines.append("Source: %s" % traj.get("loki_dir"))
    lines.append("Runs analyzed: %s" % traj.get("runs_count"))
    lines.append("")
    if traj.get("insufficient"):
        lines.append("Not enough history yet.")
        lines.append("Trust trajectory needs 2+ recorded runs to show a direction.")
        lines.append("Each `loki start` run writes a proof-of-run; come back after the next run.")
        if traj.get("notes"):
            lines.append("")
            lines.append("Notes")
            for n in traj["notes"]:
                lines.append("  - %s" % n)
        return "\n".join(lines)
    axes = traj.get("axes", {})
    lines.append("Is the agent earning autonomy on this repo?")
    for axis in ("council_pass_rate", "gate_pass_rate", "iterations", "interventions"):
        if axis in axes:
            lines.append(_fmt_axis_line(axes[axis]))
    lines.append("")
    imp = traj.get("improving_count", 0)
    reg = traj.get("regressing_count", 0)
    if imp and not reg:
        lines.append("Overall: trending more trustworthy (%d axis improving)." % imp)
    elif reg and not imp:
        lines.append("Overall: trust regressing (%d axis regressing). Review recent runs." % reg)
    elif imp or reg:
        lines.append("Overall: mixed (%d improving / %d regressing)." % (imp, reg))
    else:
        lines.append("Overall: stable.")
    if traj.get("notes"):
        lines.append("")
        lines.append("Notes")
        for n in traj["notes"]:
            lines.append("  - %s" % n)
    return "\n".join(lines)


def _resolve_loki_dir(argv):
    for i, a in enumerate(argv):
        if a == "--loki-dir" and i + 1 < len(argv):
            return argv[i + 1]
        if a.startswith("--loki-dir="):
            return a.split("=", 1)[1]
    env = os.environ.get("LOKI_DIR")
    if env:
        return env
    return os.path.join(os.getcwd(), ".loki")


def main(argv=None):
    argv = list(sys.argv[1:] if argv is None else argv)
    as_json = "--json" in argv
    no_cache = "--no-cache" in argv
    loki_dir = _resolve_loki_dir(argv)
    traj = compute_trajectory(loki_dir)
    if not no_cache:
        write_trajectory_cache(loki_dir, traj)
    if as_json:
        sys.stdout.write(format_trajectory_json(traj) + "\n")
    else:
        sys.stdout.write(format_trajectory_human(traj) + "\n")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Final-worktree diff facts shared by proof generation and verification."""

from __future__ import annotations

import os
import subprocess


_EMPTY = {"count": 0, "insertions": 0, "deletions": 0, "files": []}


def _git(repo_dir, args, allowed=(0,)):
    try:
        result = subprocess.run(
            ["git", "-C", repo_dir] + args,
            capture_output=True,
            text=True,
            encoding="utf-8",
            errors="surrogateescape",
            timeout=30,
        )
    except Exception:
        return None
    return result.stdout if result.returncode in allowed else None


def _excluded(path):
    return path == ".loki" or path.startswith(".loki/")


def _parse_numstat(raw):
    files = []
    for record in (raw or "").split("\0"):
        if not record:
            continue
        parts = record.split("\t", 2)
        if len(parts) != 3 or _excluded(parts[2]):
            continue
        ins_s, del_s, path = parts
        files.append({
            "path": path,
            "insertions": 0 if ins_s == "-" else int(ins_s),
            "deletions": 0 if del_s == "-" else int(del_s),
            "status": "binary" if ins_s == "-" else "modified",
        })
    return files


def _split_patch(raw):
    chunks = []
    current = []
    for line in (raw or "").splitlines(keepends=True):
        if line.startswith("diff --git ") and current:
            chunks.append("".join(current))
            current = [line]
        else:
            current.append(line)
    if current:
        chunks.append("".join(current))
    return chunks


def collect_workspace_diff(repo_dir, base, include_diffs=False):
    """Describe final tracked and untracked bytes relative to ``base``.

    ``git diff <base>`` compares the base tree to the final working tree, so a
    single result covers committed, staged, unstaged, and deleted tracked
    files without double counting. Git omits untracked files, which are added
    explicitly. Harness-owned ``.loki`` state is never product work.
    """
    if _git(repo_dir, ["rev-parse", "--is-inside-work-tree"]) is None:
        return dict(_EMPTY), None

    comparison = base or "HEAD~1"
    raw = _git(repo_dir, ["diff", "--no-renames", "--numstat", "-z", comparison, "--"])
    if raw is None:
        # HEAD~1 is unusable (single-commit or empty repo). Fall back to the
        # EMPTY TREE, not to a bare "HEAD".
        #
        # A bare "HEAD" compares HEAD to the working tree, so it sees only
        # UNCOMMITTED changes and silently drops everything the run committed.
        # Measured on a real greenfield run: bare HEAD reported 5 files where
        # the truth was 9. The empty tree yields "everything that now exists",
        # which is the correct answer when no earlier commit exists to diff
        # against -- and it agrees with HEAD~1 on runs where both are valid.
        empty_tree = _git(repo_dir, ["hash-object", "-t", "tree", os.devnull])
        if empty_tree:
            comparison = empty_tree.strip()
            raw = _git(repo_dir, ["diff", "--no-renames", "--numstat", "-z", comparison, "--"])
    if raw is None:
        # Last resort: worktree-only. Undercounts a run that committed its work,
        # so it is reached only when even the empty-tree diff failed.
        comparison = "HEAD"
        raw = _git(repo_dir, ["diff", "--no-renames", "--numstat", "-z", comparison, "--"])
    if raw is None:
        return dict(_EMPTY), None

    files = _parse_numstat(raw)
    diffs = [] if include_diffs else None
    if diffs is not None:
        patch = _git(repo_dir, ["diff", "--no-renames", comparison, "--"])
        for chunk in _split_patch(patch):
            first = chunk.splitlines()[0] if chunk else ""
            path = first.split(" b/", 1)[1] if " b/" in first else ""
            if not _excluded(path):
                diffs.append({"path": path, "patch": chunk})

    untracked = _git(repo_dir, ["ls-files", "--others", "--exclude-standard", "-z"])
    for path in sorted(p for p in (untracked or "").split("\0") if p and not _excluded(p)):
        stat = _git(
            repo_dir,
            ["diff", "--no-index", "--no-renames", "--numstat", "-z", "--", "/dev/null", path],
            allowed=(0, 1),
        )
        parsed = _parse_numstat(stat)
        entry = parsed[0] if parsed else {
            "path": path, "insertions": 0, "deletions": 0, "status": "untracked"
        }
        entry["path"] = path
        entry["status"] = "untracked_binary" if entry["status"] == "binary" else "untracked"
        files.append(entry)
        if diffs is not None:
            patch = _git(
                repo_dir,
                ["diff", "--no-index", "--no-renames", "--", "/dev/null", path],
                allowed=(0, 1),
            )
            if patch:
                diffs.append({"path": path, "patch": patch})

    files.sort(key=lambda item: item["path"])
    return {
        "count": len(files),
        "insertions": sum(item["insertions"] for item in files),
        "deletions": sum(item["deletions"] for item in files),
        "files": files,
    }, diffs


__all__ = ["collect_workspace_diff"]

#!/usr/bin/env python3
"""Notification trigger checker for Loki Mode.

Evaluates notification triggers against current session state
and writes alerts to .loki/notifications/active.json.

Called by run.sh after each RARV iteration.

Usage:
    python3 notification-checker.py --iteration N --loki-dir .loki
"""

import argparse
import json
import os
import random
import re
import time
from collections import deque
from datetime import datetime, timezone
from pathlib import Path


MAX_NOTIFICATIONS = 100

DEFAULT_TRIGGERS = [
    {
        "id": "budget-80pct",
        "type": "budget_threshold",
        "enabled": True,
        "threshold_pct": 80,
        "severity": "warning",
        "message": "Budget usage exceeded {pct}%",
    },
    {
        "id": "context-90pct",
        "type": "context_threshold",
        "enabled": True,
        "threshold_pct": 90,
        "severity": "critical",
        "message": "Context window at {pct}% capacity",
    },
    {
        "id": "sensitive-file",
        "type": "file_access",
        "enabled": True,
        "patterns": ["\\.env", "credentials", "\\.pem$", "\\.key$", "secret"],
        "severity": "critical",
        "message": "Sensitive file accessed: {file}",
    },
    {
        "id": "quality-gate-fail",
        "type": "quality_gate",
        "enabled": True,
        "severity": "warning",
        "message": "Quality gate failed: {gate}",
    },
    {
        "id": "stuck-iteration",
        "type": "stagnation",
        "enabled": True,
        "max_no_progress": 3,
        "severity": "warning",
        "message": "No progress detected for {count} consecutive iterations",
    },
    {
        "id": "compaction-freq",
        "type": "compaction_frequency",
        "enabled": True,
        "max_per_hour": 3,
        "severity": "warning",
        "message": "Frequent compactions: {count} in the last hour",
    },
]


def load_triggers(notif_dir):
    """Load trigger configuration, creating defaults if needed."""
    triggers_file = notif_dir / "triggers.json"
    if triggers_file.exists():
        try:
            data = json.loads(triggers_file.read_text())
            return data.get("triggers", [])
        except (json.JSONDecodeError, OSError):
            pass

    # Create default triggers
    data = {"triggers": DEFAULT_TRIGGERS}
    notif_dir.mkdir(parents=True, exist_ok=True)
    triggers_file.write_text(json.dumps(data, indent=2))
    return DEFAULT_TRIGGERS


def load_active_notifications(notif_dir):
    """Load existing notifications."""
    active_file = notif_dir / "active.json"
    if active_file.exists():
        try:
            data = json.loads(active_file.read_text())
            return data.get("notifications", [])
        except (json.JSONDecodeError, OSError):
            pass
    return []


def save_notifications(notif_dir, notifications):
    """Save notifications with pruning and summary."""
    # Prune to max
    if len(notifications) > MAX_NOTIFICATIONS:
        notifications = notifications[-MAX_NOTIFICATIONS:]

    unacked = sum(1 for n in notifications if not n.get("acknowledged", False))
    critical = sum(1 for n in notifications if n.get("severity") == "critical" and not n.get("acknowledged"))
    warning = sum(1 for n in notifications if n.get("severity") == "warning" and not n.get("acknowledged"))
    info = sum(1 for n in notifications if n.get("severity") == "info" and not n.get("acknowledged"))

    data = {
        "notifications": notifications,
        "summary": {
            "total": len(notifications),
            "unacknowledged": unacked,
            "critical": critical,
            "warning": warning,
            "info": info,
        },
    }

    active_file = notif_dir / "active.json"
    tmp_file = active_file.with_suffix(".tmp")
    tmp_file.write_text(json.dumps(data, indent=2))
    tmp_file.rename(active_file)


def make_notification(trigger_id, severity, message, iteration, data=None):
    """Create a notification entry."""
    # Include iteration and random suffix to prevent ID collision within same second
    rand_suffix = f"{random.randint(0, 0xFFFF):04x}"
    return {
        "id": f"notif-{int(time.time())}-i{iteration}-{rand_suffix}-{trigger_id}",
        "trigger_id": trigger_id,
        "severity": severity,
        "message": message,
        "timestamp": datetime.now(timezone.utc).isoformat(),
        "iteration": iteration,
        "acknowledged": False,
        "data": data or {},
    }


def already_fired(notifications, trigger_id, iteration):
    """Check if trigger already fired for this iteration."""
    return any(
        n["trigger_id"] == trigger_id and n.get("iteration") == iteration
        for n in notifications
    )


def check_budget_threshold(trigger, loki_dir, iteration, notifications):
    """Check if budget usage exceeds threshold."""
    state_file = Path(loki_dir) / "dashboard-state.json"
    if not state_file.exists():
        return None

    try:
        state = json.loads(state_file.read_text())
        budget = state.get("budget", {})
        limit = budget.get("limit", 0)
        used = budget.get("used", 0)
        if limit <= 0:
            return None
        pct = (used / limit) * 100
        threshold = trigger.get("threshold_pct", 80)
        if pct >= threshold:
            msg = trigger["message"].format(pct=f"{pct:.1f}")
            return make_notification(
                trigger["id"], trigger["severity"], msg, iteration,
                {"budget_used": used, "budget_limit": limit, "percentage": round(pct, 1)},
            )
    except (json.JSONDecodeError, OSError, KeyError):
        pass
    return None


def check_context_threshold(trigger, loki_dir, iteration, notifications):
    """Check if context window usage exceeds threshold."""
    tracking_file = Path(loki_dir) / "context" / "tracking.json"
    if not tracking_file.exists():
        return None

    try:
        tracking = json.loads(tracking_file.read_text())
        pct = tracking.get("current", {}).get("context_window_pct", 0)
        threshold = trigger.get("threshold_pct", 90)
        if pct >= threshold:
            msg = trigger["message"].format(pct=f"{pct:.1f}")
            return make_notification(
                trigger["id"], trigger["severity"], msg, iteration,
                {"context_pct": pct},
            )
    except (json.JSONDecodeError, OSError, KeyError):
        pass
    return None


def check_file_access(trigger, loki_dir, iteration, notifications):
    """Check events.jsonl for sensitive file access."""
    events_file = Path(loki_dir) / "events.jsonl"
    if not events_file.exists():
        return None

    patterns = trigger.get("patterns", [])
    if not patterns:
        return None

    # Read last 200 lines of events using deque to avoid loading entire file
    results = []
    try:
        with open(events_file, 'r') as f:
            recent = deque(f, maxlen=200)
        for line in recent:
            try:
                event = json.loads(line)
                event_data = event.get("data", "")
                if isinstance(event_data, dict):
                    event_data = json.dumps(event_data)
                for pattern in patterns:
                    if re.search(pattern, str(event_data), re.IGNORECASE):
                        # Extract file reference
                        file_ref = re.search(r'[\w./\\-]+(?:\.env|\.pem|\.key|credentials|secret)[\w./\\-]*', str(event_data))
                        file_name = file_ref.group(0) if file_ref else pattern
                        msg = trigger["message"].format(file=file_name)
                        return make_notification(
                            trigger["id"], trigger["severity"], msg, iteration,
                            {"file": file_name, "pattern": pattern},
                        )
            except json.JSONDecodeError:
                continue
    except OSError:
        pass
    return None


def check_quality_gate(trigger, loki_dir, iteration, notifications):
    """Check for quality gate failures. Reports ALL failed gates, not just first."""
    state_file = Path(loki_dir) / "dashboard-state.json"
    if not state_file.exists():
        return []

    results = []
    try:
        state = json.loads(state_file.read_text())
        gates = state.get("qualityGates", {})
        if isinstance(gates, dict):
            for gate_name, gate_data in gates.items():
                if isinstance(gate_data, dict) and gate_data.get("status") == "failed":
                    msg = trigger["message"].format(gate=gate_name)
                    results.append(make_notification(
                        trigger["id"], trigger["severity"], msg, iteration,
                        {"gate": gate_name},
                    ))
    except (json.JSONDecodeError, OSError, KeyError):
        pass
    return results if results else None


def check_stagnation(trigger, loki_dir, iteration, notifications):
    """Check for stuck iterations (no git diff changes).

    convergence.log format (pipe-delimited):
      timestamp|iteration|files_changed|CONSECUTIVE_NO_CHANGE|DONE_SIGNALS

    We parse field 4 (CONSECUTIVE_NO_CHANGE, 0-indexed field 3) from the
    most recent line to determine if stagnation exceeds the threshold.
    """
    council_file = Path(loki_dir) / "council" / "convergence.log"
    if not council_file.exists():
        return None

    try:
        # Read only the tail of the file to avoid loading everything
        with open(council_file, 'r') as f:
            lines = deque(f, maxlen=20)

        max_no_progress = trigger.get("max_no_progress", 3)

        # Parse the most recent line's CONSECUTIVE_NO_CHANGE field
        for line in reversed(lines):
            line = line.strip()
            if not line:
                continue
            fields = line.split('|')
            if len(fields) >= 4:
                try:
                    consecutive = int(fields[3])
                except (ValueError, IndexError):
                    consecutive = 0
                if consecutive >= max_no_progress:
                    msg = trigger["message"].format(count=consecutive)
                    return make_notification(
                        trigger["id"], trigger["severity"], msg, iteration,
                        {"consecutive_no_progress": consecutive},
                    )
                # Only check the most recent entry
                break
    except OSError:
        pass
    return None


def check_compaction_frequency(trigger, loki_dir, iteration, notifications):
    """Check if compactions are happening too frequently."""
    tracking_file = Path(loki_dir) / "context" / "tracking.json"
    if not tracking_file.exists():
        return None

    try:
        tracking = json.loads(tracking_file.read_text())
        compactions = tracking.get("compactions", [])
        if not compactions:
            return None

        max_per_hour = trigger.get("max_per_hour", 3)
        one_hour_ago_str = datetime.fromtimestamp(
            time.time() - 3600, tz=timezone.utc
        ).isoformat()

        recent = [
            c for c in compactions
            if c.get("timestamp", "") >= one_hour_ago_str
        ]

        if len(recent) >= max_per_hour:
            msg = trigger["message"].format(count=len(recent))
            return make_notification(
                trigger["id"], trigger["severity"], msg, iteration,
                {"compactions_last_hour": len(recent)},
            )
    except (json.JSONDecodeError, OSError, KeyError):
        pass
    return None


TRIGGER_CHECKERS = {
    "budget_threshold": check_budget_threshold,
    "context_threshold": check_context_threshold,
    "file_access": check_file_access,
    "quality_gate": check_quality_gate,
    "stagnation": check_stagnation,
    "compaction_frequency": check_compaction_frequency,
}


def check_triggers(loki_dir, iteration):
    """Evaluate all enabled triggers and generate notifications."""
    notif_dir = Path(loki_dir) / "notifications"
    notif_dir.mkdir(parents=True, exist_ok=True)

    triggers = load_triggers(notif_dir)
    notifications = load_active_notifications(notif_dir)

    new_notifications = []
    for trigger in triggers:
        if not trigger.get("enabled", True):
            continue

        trigger_type = trigger.get("type", "")
        checker = TRIGGER_CHECKERS.get(trigger_type)
        if not checker:
            continue

        # Skip if already fired for this iteration
        if already_fired(notifications, trigger["id"], iteration):
            continue

        result = checker(trigger, loki_dir, iteration, notifications)
        if result:
            # Checkers may return a single notification or a list of notifications
            if isinstance(result, list):
                new_notifications.extend(result)
            else:
                new_notifications.append(result)

    if new_notifications:
        notifications.extend(new_notifications)
        save_notifications(notif_dir, notifications)


def main():
    parser = argparse.ArgumentParser(description="Check notification triggers for Loki Mode")
    parser.add_argument("--iteration", type=int, required=True, help="Current RARV iteration number")
    parser.add_argument("--loki-dir", default=".loki", help="Path to .loki directory")
    args = parser.parse_args()

    check_triggers(args.loki_dir, args.iteration)


if __name__ == "__main__":
    main()

#!/usr/bin/env bash
#===============================================================================
# Playwright Smoke Test Module (v5.46.0)
#
# Runs lightweight smoke tests against a running user application to verify
# it loads correctly. Advisory only - failures do NOT block iterations or
# council approval.
#
# Functions:
#   playwright_verify_init()        - Check/install Playwright
#   playwright_verify_app(url)      - Run smoke test against URL
#   playwright_verify_should_run()  - Check if verification should run
#   playwright_verify_summary()     - One-line summary for prompt injection
#   playwright_verify_as_evidence() - Formatted output for council evidence
#
# Environment Variables:
#   LOKI_PLAYWRIGHT_ENABLED    - Enable/disable (default: true)
#   LOKI_PLAYWRIGHT_INTERVAL   - Run every N iterations (default: 5)
#   LOKI_PLAYWRIGHT_TIMEOUT    - Page load timeout in ms (default: 15000)
#
# Data:
#   .loki/verification/playwright-results.json  - Last results
#   .loki/verification/screenshots/             - Captured screenshots
#
#===============================================================================

# Configuration
PLAYWRIGHT_ENABLED=${LOKI_PLAYWRIGHT_ENABLED:-true}
PLAYWRIGHT_INTERVAL=${LOKI_PLAYWRIGHT_INTERVAL:-5}
# Guard against zero/negative interval (division by zero in modulo)
if [ "$PLAYWRIGHT_INTERVAL" -le 0 ] 2>/dev/null; then
    PLAYWRIGHT_INTERVAL=5
fi
PLAYWRIGHT_TIMEOUT=${LOKI_PLAYWRIGHT_TIMEOUT:-15000}
# Derive seconds for the outer timeout wrapper (add buffer for browser startup)
PLAYWRIGHT_TIMEOUT_SEC=$(( (PLAYWRIGHT_TIMEOUT / 1000) + 15 ))

# Internal state
PLAYWRIGHT_VERIFY_DIR=""
PLAYWRIGHT_RESULTS_FILE=""
PLAYWRIGHT_LAST_VERIFY_ITERATION=0
PLAYWRIGHT_AVAILABLE=false
PLAYWRIGHT_MAX_SCREENSHOTS=10

#===============================================================================
# Initialization
#===============================================================================

playwright_verify_init() {
    # Check if npx playwright is available; attempt chromium install if needed.
    # Returns 0 if playwright available, 1 if not.

    if [ "$PLAYWRIGHT_ENABLED" != "true" ]; then
        return 1
    fi

    PLAYWRIGHT_VERIFY_DIR=".loki/verification"
    PLAYWRIGHT_RESULTS_FILE="${PLAYWRIGHT_VERIFY_DIR}/playwright-results.json"
    mkdir -p "${PLAYWRIGHT_VERIFY_DIR}/screenshots"

    # Check if playwright is accessible via npx
    if ! npx playwright --version &>/dev/null; then
        log_warn "Playwright not found via npx - smoke tests disabled"
        PLAYWRIGHT_AVAILABLE=false
        return 1
    fi

    # Check if chromium browser is installed; attempt install if not
    if ! npx playwright install --dry-run chromium &>/dev/null; then
        log_info "Installing Playwright chromium browser..."
        if ! timeout 60 npx playwright install chromium &>/dev/null; then
            log_warn "Failed to install Playwright chromium - smoke tests disabled"
            PLAYWRIGHT_AVAILABLE=false
            return 1
        fi
    fi

    PLAYWRIGHT_AVAILABLE=true
    log_info "Playwright smoke tests initialized (every ${PLAYWRIGHT_INTERVAL} iterations, ${PLAYWRIGHT_TIMEOUT}ms timeout)"
    return 0
}

#===============================================================================
# Interval Control
#===============================================================================

playwright_verify_should_run() {
    # Returns 0 (true) if verification should run this iteration
    if [ "$PLAYWRIGHT_ENABLED" != "true" ]; then
        return 1
    fi

    if [ "$PLAYWRIGHT_AVAILABLE" != "true" ]; then
        return 1
    fi

    local current_iteration="${ITERATION_COUNT:-0}"
    if [ "$current_iteration" -eq 0 ]; then
        return 1
    fi

    if [ $((current_iteration % PLAYWRIGHT_INTERVAL)) -ne 0 ]; then
        return 1
    fi

    # Don't verify same iteration twice
    if [ "$current_iteration" -eq "$PLAYWRIGHT_LAST_VERIFY_ITERATION" ]; then
        return 1
    fi

    return 0
}

#===============================================================================
# Smoke Test
#===============================================================================

playwright_verify_app() {
    local url="$1"

    if [ -z "$url" ]; then
        log_warn "playwright_verify_app: no URL provided"
        return 0
    fi

    local verify_dir="${PLAYWRIGHT_VERIFY_DIR:-.loki/verification}"
    local screenshots_dir="${verify_dir}/screenshots"
    mkdir -p "$screenshots_dir"

    local timestamp
    timestamp=$(date -u +%Y-%m-%dT%H%M%SZ)
    local screenshot_path="${screenshots_dir}/verify-${timestamp}.png"
    local results_file="${verify_dir}/playwright-results.json"
    local script_file="${verify_dir}/.smoke-test.js"

    log_step "Running Playwright smoke test against ${url}..."

    # Generate inline smoke test script
    cat > "$script_file" << 'SMOKE_SCRIPT'
const { chromium } = require('playwright');

(async () => {
  const url = process.argv[2];
  const screenshotPath = process.argv[3];
  const resultsPath = process.argv[4];
  const pageTimeout = parseInt(process.argv[5] || '15000', 10);
  const startTime = Date.now();

  const results = {
    verified_at: new Date().toISOString(),
    url: url,
    passed: false,
    checks: {
      page_loads: false,
      no_5xx: false,
      no_console_errors: true,
      has_title: false,
      has_content: false
    },
    screenshot: screenshotPath,
    errors: [],
    duration_ms: 0
  };

  let browser;
  try {
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();

    // Collect console errors
    const consoleErrors = [];
    page.on('console', msg => {
      if (msg.type() === 'error') consoleErrors.push(msg.text());
    });

    // Navigate to URL
    const response = await page.goto(url, {
      waitUntil: 'domcontentloaded',
      timeout: pageTimeout
    });
    results.checks.page_loads = true;

    // Check HTTP status (no 5xx)
    const status = response ? response.status() : 0;
    results.checks.no_5xx = status < 500;
    if (status >= 500) results.errors.push('HTTP ' + status);

    // Check console errors
    if (consoleErrors.length > 0) {
      results.checks.no_console_errors = false;
      results.errors.push(...consoleErrors.slice(0, 5));
    }

    // Check page title
    const title = await page.title();
    results.checks.has_title = title.length > 0;

    // Check visible content
    const bodyText = await page.evaluate(() => document.body?.innerText?.trim() || '');
    results.checks.has_content = bodyText.length > 0;

    // Capture screenshot
    await page.screenshot({ path: screenshotPath, fullPage: false });

    // Determine overall pass
    results.passed = Object.values(results.checks).every(v => v === true);

  } catch (err) {
    results.errors.push(err.message);
  } finally {
    if (browser) await browser.close();
    results.duration_ms = Date.now() - startTime;

    // Atomic write: temp file then rename
    const fs = require('fs');
    const tmp = resultsPath + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(results, null, 2));
    fs.renameSync(tmp, resultsPath);
  }

  process.exit(results.passed ? 0 : 1);
})();
SMOKE_SCRIPT

    # Run with outer timeout (never block iteration)
    timeout "${PLAYWRIGHT_TIMEOUT_SEC}" node "$script_file" \
        "$url" "$screenshot_path" "$results_file" "$PLAYWRIGHT_TIMEOUT" 2>/dev/null
    local exit_code=$?

    # Clean up generated script
    rm -f "$script_file"

    # Update tracking state
    PLAYWRIGHT_LAST_VERIFY_ITERATION="${ITERATION_COUNT:-0}"

    # Rotate screenshots: keep only the most recent N
    _playwright_rotate_screenshots "$screenshots_dir"

    # Log result
    if [ -f "$results_file" ]; then
        local summary
        summary=$(playwright_verify_summary 2>/dev/null || true)
        if [ -n "$summary" ]; then
            log_info "Playwright: $summary"
        fi
    elif [ "$exit_code" -eq 124 ]; then
        log_warn "Playwright smoke test timed out after ${PLAYWRIGHT_TIMEOUT_SEC}s"
    else
        log_warn "Playwright smoke test failed (exit $exit_code)"
    fi

    # Never fail the iteration
    return 0
}

#===============================================================================
# Functional Proof (Proof-of-Function dynamic half) -- PERSISTENCE + AUTH
#===============================================================================
#
# Drives the RUNNING app and writes .loki/verification/functional-proof.json
# with an explicit tri-state per property that council_evidence_gate reads:
#   {"persistence": {"attempted": bool, "proven": bool, "reason": str},
#    "auth":        {"attempted": bool, "proven": bool, "reason": str},
#    "url": str, "verified_at": str}
#
# PERSISTENCE: discovers a create path (a <form> with a submit, or an Add/Create/
#   Save button), fills it with a UNIQUE sentinel token (loki-persist-<uuid>),
#   submits, waits for network idle, RELOADS, and asserts the sentinel is present
#   after reload (a real DB/API read-back). proven=false if it does not survive
#   -> the gate BLOCKS. no create path -> attempted:false reason=no_create_path.
#
# AUTH: if an auth signal is detected (a login/signin route/link, or
#   LOKI_PROOF_PROTECTED_PATH configured), issues a logged-out request to a
#   protected route and asserts REJECTION (401/403 or redirect to login).
#   A login screen that merely renders -> proven:false -> BLOCK. No auth signal
#   -> attempted:false reason=no_auth.
#
# Never blocks the iteration itself (|| true at the call site). The council gate
# is what turns proven:false into a BLOCK. Interval + serveable gated upstream.
# Opt out per-axis with LOKI_PROOF_PERSIST=0 / LOKI_PROOF_AUTH=0 at the gate.
#
# Env knobs:
#   LOKI_PROOF_CREATE_SELECTOR  - CSS selector to point the driver at a form
#   LOKI_PROOF_PROTECTED_PATH   - path to test for a logged-out rejection
#   LOKI_PROOF_RELOAD_WAIT_MS   - wait before asserting sentinel absence (flake)
#===============================================================================

playwright_prove_functional() {
    local url="$1"

    if [ -z "$url" ]; then
        log_warn "playwright_prove_functional: no URL provided"
        return 0
    fi

    local verify_dir="${PLAYWRIGHT_VERIFY_DIR:-.loki/verification}"
    local screenshots_dir="${verify_dir}/screenshots"
    mkdir -p "$screenshots_dir"

    local results_file="${verify_dir}/functional-proof.json"
    local script_file="${verify_dir}/.functional-proof.js"

    # BUG 1a: invalidate any PRIOR proof BEFORE driving. A timeout (exit 124) or a
    # driver hang must not leave a stale proven:true from an earlier iteration that
    # the gate would read as current. The node script re-writes a fresh, stamped
    # proof in its finally; if it never gets there, the file stays absent (which
    # the gate treats as inconclusive pass-through, never a stale green).
    rm -f "$results_file" "$results_file.tmp" 2>/dev/null || true

    log_step "Running Playwright functional proof (persistence + auth) against ${url}..."

    # Freshness stamp: the current iteration and the current HEAD SHA. The council
    # gate reads this and treats a proof whose iteration does not match the current
    # ITERATION_COUNT as NOT PRESENT (inconclusive), so a stale file never passes.
    local _proof_iter="${ITERATION_COUNT:-0}"
    local _proof_head
    _proof_head="$(git rev-parse HEAD 2>/dev/null || echo '')"

    cat > "$script_file" << 'PROOF_SCRIPT'
(async () => {
  const url = process.argv[2];
  const resultsPath = process.argv[3];
  const pageTimeout = parseInt(process.argv[4] || '15000', 10);
  const reloadWaitMs = parseInt(process.env.LOKI_PROOF_RELOAD_WAIT_MS || '1500', 10);
  const createSelector = process.env.LOKI_PROOF_CREATE_SELECTOR || '';
  const protectedPath = process.env.LOKI_PROOF_PROTECTED_PATH || '';
  // Authorization / tenant-isolation knobs (all optional; absence => auto-detect
  // or inconclusive pass-through). Configured selectors are the highest-confidence
  // path; auto-detect (signup form) is the best-effort fallback.
  const azSignupSel = process.env.LOKI_PROOF_AUTHZ_SIGNUP_SELECTOR || '';
  const azLoginSel = process.env.LOKI_PROOF_AUTHZ_LOGIN_SELECTOR || '';
  const azUserField = process.env.LOKI_PROOF_AUTHZ_USER_FIELD || '';
  const azPassField = process.env.LOKI_PROOF_AUTHZ_PASS_FIELD || '';
  const azSubmitSel = process.env.LOKI_PROOF_AUTHZ_SUBMIT || '';
  const azOwnedListSel = process.env.LOKI_PROOF_AUTHZ_OWNED_LIST_SELECTOR || '';
  const azDetailTemplate = process.env.LOKI_PROOF_AUTHZ_DETAIL_URL_TEMPLATE || '';
  const azApiTemplate = process.env.LOKI_PROOF_AUTHZ_API_TEMPLATE || '';

  const results = {
    verified_at: new Date().toISOString(),
    url: url,
    // BUG 1b: freshness stamp the gate validates against the current iteration.
    stamp: {
      iteration: parseInt(process.env.LOKI_PROOF_ITER || '0', 10),
      head: process.env.LOKI_PROOF_HEAD || '',
    },
    persistence: { attempted: false, proven: false, reason: 'not_run' },
    auth: { attempted: false, proven: false, reason: 'not_run' },
    authorization: { attempted: false, proven: false, reason: 'not_run' },
  };

  const write = () => {
    const fs = require('fs');
    const tmp = resultsPath + '.tmp';
    fs.writeFileSync(tmp, JSON.stringify(results, null, 2));
    fs.renameSync(tmp, resultsPath);
  };

  let browser;
  try {
    // BUG 3: require playwright INSIDE the try. If the driver is absent, node
    // would otherwise throw at module-top require time and write NO proof at all
    // -- which, combined with the missing-file handling, previously false-blocked.
    // A fresh fallback proof {attempted:false, reason:driver_unavailable} keeps
    // the axis inconclusive pass-through instead.
    const { chromium } = require('playwright');
    browser = await chromium.launch({ headless: true });
    const page = await browser.newPage();
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: pageTimeout });

    // ---- PERSISTENCE ----
    try {
      const sentinel = 'loki-persist-' + Math.random().toString(36).slice(2, 10);
      // Find a create path: a configured selector, else a form with a text input
      // and a submit, else an Add/Create/Save button revealing a form.
      let formHandle = null;
      if (createSelector) {
        formHandle = await page.$(createSelector);
      }
      if (!formHandle) {
        // Try to reveal a form behind an Add/Create/New/Save trigger.
        const trigger = await page.$(
          'button:has-text("Add"), button:has-text("Create"), button:has-text("New"), a:has-text("Add"), a:has-text("Create")'
        ).catch(() => null);
        if (trigger) { await trigger.click().catch(() => {}); await page.waitForTimeout(300); }
        formHandle = await page.$('form');
      }

      // Locate a fillable text input inside/near the form.
      let input = null;
      if (formHandle) {
        input = await formHandle.$('input[type="text"], input:not([type]), input[type="search"], input[type="email"], textarea').catch(() => null);
      }
      if (!input) {
        input = await page.$('input[type="text"], input:not([type]), textarea').catch(() => null);
      }

      if (!input) {
        results.persistence = { attempted: false, proven: false, reason: 'no_create_path' };
      } else {
        results.persistence.attempted = true;
        await input.fill(sentinel);
        // Submit: prefer a submit button, else press Enter.
        let submitted = false;
        const submitBtn = formHandle
          ? await formHandle.$('button[type="submit"], input[type="submit"], button:has-text("Add"), button:has-text("Create"), button:has-text("Save"), button:has-text("Submit")').catch(() => null)
          : null;
        try {
          if (submitBtn) { await submitBtn.click(); submitted = true; }
          else { await input.press('Enter'); submitted = true; }
        } catch (e) { submitted = false; }

        if (!submitted) {
          results.persistence = { attempted: true, proven: false, reason: 'submit_failed' };
        } else {
          // Wait for the write to settle, then read back in a FRESH context with
          // NO client storage. BUG 3: a plain page.reload() keeps localStorage /
          // sessionStorage / IndexedDB, so a no-backend SPA that only persists to
          // localStorage would falsely prove persistence. A brand-new context
          // (fresh cookies + empty storage) only sees the sentinel if it survived
          // in a real DB/API the server read back -- true beyond-client persistence.
          await page.waitForLoadState('networkidle', { timeout: pageTimeout }).catch(() => {});
          await page.waitForTimeout(reloadWaitMs);
          const readCtx = await browser.newContext();
          const readPage = await readCtx.newPage();
          await readPage.goto(url, { waitUntil: 'networkidle', timeout: pageTimeout }).catch(() => {});
          const body = await readPage.content();
          await readCtx.close().catch(() => {});
          if (body.indexOf(sentinel) !== -1) {
            results.persistence = { attempted: true, proven: true, reason: 'sentinel_survived_fresh_context', sentinel };
          } else {
            results.persistence = { attempted: true, proven: false, reason: 'sentinel_gone_after_reload', sentinel };
          }
        }
      }
    } catch (e) {
      // A create path was found but the drive errored -> proven:false (BLOCK).
      // "submit errored" is the #1 churn bug and must not green-wash.
      results.persistence = { attempted: true, proven: false, reason: 'drive_error: ' + String(e.message).slice(0, 120) };
    }

    // ---- AUTH (negative path) ----
    try {
      // Detect an auth signal: a configured protected path, or a login/signin
      // route/link in the app.
      let path = protectedPath;
      let authSignal = !!protectedPath;
      if (!authSignal) {
        // Re-load the app root (persistence may have navigated it) and look.
        await page.goto(url, { waitUntil: 'domcontentloaded', timeout: pageTimeout }).catch(() => {});
        const hasLogin = await page.$('a[href*="login"], a[href*="signin"], a:has-text("Log in"), a:has-text("Login"), a:has-text("Sign in"), form[action*="login"], input[type="password"]').catch(() => null);
        authSignal = !!hasLogin;
        // Guess a protected path from common conventions.
        if (authSignal) {
          for (const cand of ['/dashboard', '/account', '/admin', '/app', '/settings', '/profile']) {
            path = cand; break;
          }
        }
      }

      if (!authSignal) {
        results.auth = { attempted: false, proven: false, reason: 'no_auth' };
      } else if (!path) {
        results.auth = { attempted: false, proven: false, reason: 'auth_detected_untestable' };
      } else {
        results.auth.attempted = true;
        // Logged-out request in a FRESH context (no cookies/storage).
        const ctx = await browser.newContext();
        const p2 = await ctx.newPage();
        const target = new URL(path, url).toString();
        let observed = 'none';
        const resp = await p2.goto(target, { waitUntil: 'domcontentloaded', timeout: pageTimeout }).catch(() => null);
        const status = resp ? resp.status() : 0;
        const finalUrl = p2.url();
        const redirectedToLogin = /login|signin|sign-in|auth/i.test(finalUrl) && finalUrl !== target;
        const hasPasswordField = await p2.$('input[type="password"]').catch(() => null);
        if (status === 401 || status === 403) {
          observed = String(status);
          results.auth = { attempted: true, proven: true, reason: 'rejected_' + status, path, observed_status: status };
        } else if (redirectedToLogin) {
          observed = 'redirect';
          results.auth = { attempted: true, proven: true, reason: 'redirect_to_login', path, observed_status: 'redirect' };
        } else if (status >= 200 && status < 300 && !hasPasswordField) {
          // Protected route served content logged-out -> auth NOT enforced.
          results.auth = { attempted: true, proven: false, reason: 'served_200_logged_out', path, observed_status: status };
        } else if (hasPasswordField) {
          // A login screen merely rendered at the protected path. That is not
          // enforcement of the protected resource; but it is also not a served
          // resource. Treat as untestable (a protected page that IS the login).
          results.auth = { attempted: true, proven: false, reason: 'login_screen_only', path, observed_status: status };
        } else {
          results.auth = { attempted: true, proven: false, reason: 'auth_detected_untestable', path, observed_status: status };
        }
        await ctx.close().catch(() => {});
      }
    } catch (e) {
      results.auth = { attempted: true, proven: false, reason: 'auth_detected_timeout' };
    }

    // ---- AUTHORIZATION (tenant isolation) ----
    // The Lovable-breach class: two LOGGED-IN users where A can read B's owned
    // rows. Prove by OBSERVED artifact only -- a real second session actually
    // being DENIED A's sentinel. The ONLY blocking verdict is a fresh positive
    // leak (reason prefix 'user_b_read_user_a_'); every undetectable/absent case
    // is attempted:false or a non-leak reason -> inconclusive pass-through.
    try {
      // rand sentinel + two distinct identities.
      const rnd = () => Math.random().toString(36).slice(2, 10);
      const sentinel = 'loki-authz-' + rnd();
      const identityA = 'authzA-' + rnd() + '@loki.test';
      const identityB = 'authzB-' + rnd() + '@loki.test';
      const pass = 'Loki-authz-Pw1!';

      // Locate a signup/login form in a page. Returns {user, pass, submit} handles
      // or null. Configured selectors win; else auto-detect a password field + a
      // text/email input + a submit.
      const findAuthForm = async (pg, isSignup) => {
        let userH = null, passH = null, submitH = null;
        if (azUserField) userH = await pg.$(azUserField).catch(() => null);
        if (azPassField) passH = await pg.$(azPassField).catch(() => null);
        if (azSubmitSel) submitH = await pg.$(azSubmitSel).catch(() => null);
        const scopeSel = isSignup ? azSignupSel : azLoginSel;
        if (scopeSel) {
          const scope = await pg.$(scopeSel).catch(() => null);
          if (scope) {
            if (!userH) userH = await scope.$('input[type="email"], input[type="text"], input:not([type])').catch(() => null);
            if (!passH) passH = await scope.$('input[type="password"]').catch(() => null);
            if (!submitH) submitH = await scope.$('button[type="submit"], input[type="submit"], button').catch(() => null);
          }
        }
        if (!passH) passH = await pg.$('input[type="password"]').catch(() => null);
        if (!passH) return null;
        if (!userH) userH = await pg.$('input[type="email"], input[type="text"], input:not([type])').catch(() => null);
        if (!userH) return null;
        if (!submitH) submitH = await pg.$('button[type="submit"], input[type="submit"], button:has-text("Sign up"), button:has-text("Sign in"), button:has-text("Log in"), button:has-text("Register"), button:has-text("Continue")').catch(() => null);
        return { userH, passH, submitH };
      };

      // Authenticate a fresh context as (email). Prefer signup (guarantees a fresh
      // distinct user); fall back to login only if a login form is present.
      // Returns {ctx, page} on success or null.
      const authAs = async (email) => {
        const ctx = await browser.newContext();
        const pg = await ctx.newPage();
        // Try signup route first, then app root.
        let form = null;
        for (const cand of ['/signup', '/register', '/sign-up', '/']) {
          const target = new URL(cand, url).toString();
          await pg.goto(target, { waitUntil: 'domcontentloaded', timeout: pageTimeout }).catch(() => {});
          form = await findAuthForm(pg, true);
          if (form) break;
        }
        if (!form) { await ctx.close().catch(() => {}); return null; }
        try {
          await form.userH.fill(email);
          await form.passH.fill(pass);
          if (form.submitH) { await form.submitH.click().catch(() => {}); }
          else { await form.passH.press('Enter').catch(() => {}); }
          await pg.waitForLoadState('networkidle', { timeout: pageTimeout }).catch(() => {});
          await pg.waitForTimeout(reloadWaitMs);
        } catch (e) { await ctx.close().catch(() => {}); return null; }
        return { ctx, page: pg };
      };

      // Step 1a: two-session capability. If neither configured nor an auto signup
      // path exists, this authAs returns null and we bail as no_multiuser_auth.
      const sessA = await authAs(identityA);
      if (!sessA) {
        results.authorization = { attempted: false, proven: false, reason: 'no_multiuser_auth', identity_a: identityA };
      } else {
        // Step 1b + 2: as A, create an owned record with the sentinel (reuse the
        // persistence create-path finder shape).
        const pgA = sessA.page;
        let createInput = null;
        let formHandleA = null;
        if (createSelector) formHandleA = await pgA.$(createSelector).catch(() => null);
        if (!formHandleA) {
          const trig = await pgA.$('button:has-text("Add"), button:has-text("Create"), button:has-text("New"), a:has-text("Add"), a:has-text("Create")').catch(() => null);
          if (trig) { await trig.click().catch(() => {}); await pgA.waitForTimeout(300); }
          formHandleA = await pgA.$('form').catch(() => null);
        }
        if (formHandleA) createInput = await formHandleA.$('input[type="text"], input:not([type]), input[type="search"], textarea').catch(() => null);
        if (!createInput) createInput = await pgA.$('input[type="text"], input:not([type]), textarea').catch(() => null);

        if (!createInput) {
          results.authorization = { attempted: false, proven: false, reason: 'no_owned_data', identity_a: identityA };
          await sessA.ctx.close().catch(() => {});
        } else {
          await createInput.fill(sentinel);
          const submitBtnA = formHandleA
            ? await formHandleA.$('button[type="submit"], input[type="submit"], button:has-text("Add"), button:has-text("Create"), button:has-text("Save"), button:has-text("Submit")').catch(() => null)
            : null;
          try {
            if (submitBtnA) await submitBtnA.click();
            else await createInput.press('Enter');
          } catch (e) {}
          await pgA.waitForLoadState('networkidle', { timeout: pageTimeout }).catch(() => {});
          await pgA.waitForTimeout(reloadWaitMs);
          // Capture the list route A saw and any detail URL/id after create.
          const listRouteA = azOwnedListSel ? '' : new URL(pgA.url(), url).pathname;
          const afterCreateUrl = pgA.url();
          // Extract a plausible record id from the post-create URL (/items/123).
          let recordId = '';
          const idMatch = afterCreateUrl.match(/\/(\d+|[0-9a-f]{8,})(?:[/?#].*)?$/i);
          if (idMatch) recordId = idMatch[1];
          const detailUrlA = (afterCreateUrl !== url && /\/(\d+|[0-9a-f]{8,})/.test(afterCreateUrl)) ? afterCreateUrl : '';
          await sessA.ctx.close().catch(() => {});

          // Step 3: session B in a SEPARATE fresh context.
          const sessB = await authAs(identityB);
          if (!sessB) {
            results.authorization = { attempted: false, proven: false, reason: 'could_not_create_second_user', sentinel, identity_a: identityA, identity_b: identityB };
          } else {
            const pgB = sessB.page;
            // Distinctness guard: if B's initial view already shows A's sentinel
            // as a BASELINE (single-user app silently reused A), we cannot tell a
            // leak from a shared store -> inconclusive.
            const baselineB = await pgB.content().catch(() => '');
            if (baselineB.indexOf(sentinel) !== -1) {
              results.authorization = { attempted: false, proven: false, reason: 'could_not_create_second_user', sentinel, identity_a: identityA, identity_b: identityB };
              await sessB.ctx.close().catch(() => {});
            } else {
              // Step 4: as B, attempt to READ A's sentinel via every path.
              const pathsTried = [];
              let leakPath = '';

              // (a) list view: the configured owned-list route, else the route A saw.
              let listTarget = '';
              if (azOwnedListSel && /^https?:|^\//.test(azOwnedListSel)) listTarget = azOwnedListSel;
              else if (listRouteA) listTarget = listRouteA;
              if (listTarget) {
                const t = new URL(listTarget, url).toString();
                const r = await pgB.goto(t, { waitUntil: 'networkidle', timeout: pageTimeout }).catch(() => null);
                const st = r ? r.status() : 0;
                let contained = false;
                try {
                  // If configured, scope the read to the owned-list selector.
                  if (azOwnedListSel && !/^https?:|^\//.test(azOwnedListSel)) {
                    const el = await pgB.$(azOwnedListSel).catch(() => null);
                    const txt = el ? await el.textContent().catch(() => '') : await pgB.content().catch(() => '');
                    contained = (txt || '').indexOf(sentinel) !== -1;
                  } else {
                    contained = (await pgB.content().catch(() => '')).indexOf(sentinel) !== -1;
                  }
                } catch (e) {}
                pathsTried.push({ path: 'list', target: t, observed_status: st, contained_sentinel: contained });
                if (contained) leakPath = leakPath || 'list';
              }

              // (b) direct object (IDOR): a detail URL/template navigated in B's ctx.
              let detailTarget = '';
              if (azDetailTemplate && recordId) detailTarget = azDetailTemplate.replace('{id}', recordId);
              else if (detailUrlA) detailTarget = detailUrlA;
              if (detailTarget) {
                const t = new URL(detailTarget, url).toString();
                const r = await pgB.goto(t, { waitUntil: 'domcontentloaded', timeout: pageTimeout }).catch(() => null);
                const st = r ? r.status() : 0;
                const body = await pgB.content().catch(() => '');
                const contained = st >= 200 && st < 300 && body.indexOf(sentinel) !== -1;
                pathsTried.push({ path: 'detail', target: t, observed_status: st, contained_sentinel: contained });
                if (contained) leakPath = leakPath || 'detail';
              }

              // (c) API: configured template in B's cookie context via fetch.
              let apiTarget = '';
              if (azApiTemplate) apiTarget = azApiTemplate.replace('{id}', recordId || '');
              if (apiTarget) {
                const t = new URL(apiTarget, url).toString();
                let st = 0, body = '';
                try {
                  const resp = await pgB.request.get(t, { timeout: pageTimeout });
                  st = resp.status();
                  body = await resp.text().catch(() => '');
                } catch (e) {}
                const contained = st >= 200 && st < 300 && body.indexOf(sentinel) !== -1;
                pathsTried.push({ path: 'api', target: t, observed_status: st, contained_sentinel: contained });
                if (contained) leakPath = leakPath || 'api';
              }

              await sessB.ctx.close().catch(() => {});

              // Step 5: verdict.
              if (pathsTried.length === 0) {
                // Created data but no list/detail/api to read it as B. INCONCLUSIVE.
                results.authorization = { attempted: true, proven: false, reason: 'no_read_path_for_b', sentinel, identity_a: identityA, identity_b: identityB, paths_tried: pathsTried };
              } else if (leakPath) {
                // POSITIVE LEAK: B's real session received A's sentinel. The ONLY block.
                results.authorization = { attempted: true, proven: false, reason: 'user_b_read_user_a_' + leakPath, sentinel, identity_a: identityA, identity_b: identityB, paths_tried: pathsTried };
              } else {
                // Isolation HOLDS: B was denied on every path actually tried.
                results.authorization = { attempted: true, proven: true, reason: 'isolated_on_all_paths', sentinel, identity_a: identityA, identity_b: identityB, paths_tried: pathsTried };
              }
            }
          }
        }
      }
    } catch (e) {
      // Deliberate asymmetry vs persistence: our own driver error is NOT a proof
      // of a leak. Map to inconclusive (the gate treats authz_drive_error:* as
      // pass-through). A security property must never be DISPROVEN by our tooling.
      results.authorization = { attempted: true, proven: false, reason: 'authz_drive_error: ' + String(e && e.message || e).slice(0, 120) };
    }

  } catch (err) {
    // Two inconclusive-passthrough cases land here, both non-blocking:
    //   - the playwright driver could not be required/launched -> driver_unavailable
    //   - the app was unreachable at all -> not_serveable
    const msg = String(err && err.message || err);
    const driverGone = /Cannot find module 'playwright'|Cannot find package 'playwright'|playwright.*not.*found|browserType.launch/i.test(msg);
    const reason = driverGone ? 'driver_unavailable' : 'not_serveable';
    results.persistence = { attempted: false, proven: false, reason };
    results.auth = { attempted: false, proven: false, reason };
    results.authorization = { attempted: false, proven: false, reason };
    results.error = msg.slice(0, 160);
  } finally {
    if (browser) await browser.close();
    write();
  }

  process.exit(0);
})();
PROOF_SCRIPT

    # Run with outer timeout (never block iteration). A timeout leaves NO proof
    # (we deleted the prior file above and the script only writes in its finally);
    # a hung app therefore reads as inconclusive, never as a stale green.
    timeout "${PLAYWRIGHT_TIMEOUT_SEC}" \
        env LOKI_PROOF_ITER="$_proof_iter" LOKI_PROOF_HEAD="$_proof_head" \
        node "$script_file" \
        "$url" "$results_file" "$PLAYWRIGHT_TIMEOUT" 2>/dev/null
    local exit_code=$?

    rm -f "$script_file"

    if [ "$exit_code" -eq 124 ]; then
        log_warn "Playwright functional proof timed out after ${PLAYWRIGHT_TIMEOUT_SEC}s (proof left inconclusive)"
    elif [ -f "$results_file" ]; then
        local psummary
        psummary=$(_PF="$results_file" python3 -c "
import json, os
try:
    d = json.load(open(os.environ['_PF']))
    p = d.get('persistence', {}); a = d.get('auth', {}); z = d.get('authorization', {})
    print('persistence attempted=%s proven=%s (%s) | auth attempted=%s proven=%s (%s) | authz attempted=%s proven=%s (%s)' % (
        p.get('attempted'), p.get('proven'), p.get('reason'),
        a.get('attempted'), a.get('proven'), a.get('reason'),
        z.get('attempted'), z.get('proven'), z.get('reason')))
except Exception:
    print('')
" 2>/dev/null || true)
        [ -n "$psummary" ] && log_info "Playwright functional proof: $psummary"
    fi

    return 0
}

#===============================================================================
# Screenshot Rotation
#===============================================================================

_playwright_rotate_screenshots() {
    local dir="$1"
    local max=${PLAYWRIGHT_MAX_SCREENSHOTS}

    # Count existing screenshots
    local count
    count=$(find "$dir" -maxdepth 1 -name 'verify-*.png' 2>/dev/null | wc -l | tr -d ' ')

    if [ "$count" -gt "$max" ]; then
        local to_remove=$((count - max))
        # Remove oldest files (sorted by name, which is timestamp-based)
        find "$dir" -maxdepth 1 -name 'verify-*.png' 2>/dev/null \
            | sort | head -n "$to_remove" \
            | xargs rm -f 2>/dev/null || true
    fi
}

#===============================================================================
# Summary (for prompt injection)
#===============================================================================

playwright_verify_summary() {
    # Returns one-line summary string
    if [ ! -f "$PLAYWRIGHT_RESULTS_FILE" ]; then
        echo ""
        return 0
    fi

    _PW_RESULTS="$PLAYWRIGHT_RESULTS_FILE" python3 -c "
import json, os
try:
    data = json.load(open(os.environ['_PW_RESULTS']))
    checks = data.get('checks', {})
    passed = sum(1 for v in checks.values() if v)
    total = len(checks)
    status = 'PASS' if data.get('passed') else 'FAIL'
    duration = data.get('duration_ms', 0)
    url = data.get('url', '?')
    errors = data.get('errors', [])
    err_detail = ''
    if errors:
        err_detail = ' Errors: ' + '; '.join(errors[:3])
    print(f'{status} {passed}/{total} checks ({duration}ms) {url}{err_detail}')
except Exception:
    print('')
" 2>/dev/null || echo ""
}

#===============================================================================
# Council Evidence (for completion-council.sh)
#===============================================================================

playwright_verify_as_evidence() {
    # Writes formatted smoke test evidence to stdout or appends to file
    local evidence_file="${1:-}"

    if [ ! -f "$PLAYWRIGHT_RESULTS_FILE" ]; then
        return 0
    fi

    {
        echo ""
        echo "## Playwright Smoke Test"
        echo ""

        _PW_RESULTS="$PLAYWRIGHT_RESULTS_FILE" python3 -c "
import json, os
try:
    data = json.load(open(os.environ['_PW_RESULTS']))
    checks = data.get('checks', {})
    status = 'PASS' if data.get('passed') else 'FAIL'
    print(f'Overall: {status} | URL: {data.get(\"url\", \"?\")} | Duration: {data.get(\"duration_ms\", 0)}ms')
    print()
    for name, result in checks.items():
        label = '[PASS]' if result else '[FAIL]'
        print(f'  {label} {name}')
    errors = data.get('errors', [])
    if errors:
        print()
        print('Errors:')
        for e in errors[:5]:
            print(f'  - {e}')
    screenshot = data.get('screenshot', '')
    if screenshot:
        print()
        print(f'Screenshot: {screenshot}')
except Exception:
    print('Playwright data unavailable')
" 2>/dev/null || echo "Playwright data unavailable"
    } >> "${evidence_file:-/dev/stdout}"
}
